// ------------------------------------------------------------- the menu bar
//
// Menus are {id, title, items, right}; an item is {label, onClick, mark}, a rule
// is null. A title is inverted while its menu is open; a menu open goes over to
// another title the pointer moves onto.
function MenuBar({ app, menus, height, corners }) {
  const open = app.state.menu || null
  const menuH = size(20)
  const toggle = (id) => () => frameos.setState('menu', open === id ? null : id)
  const slide = (id) => (open && open !== id ? () => frameos.setState('menu', id) : undefined)
  const itemH = size(18)
  return (
    <div className={`absolute left-0 top-0 w-full h-[${menuH}px] flex items-center px-[${px(8)}] bg-white text-black border-b-${edge} border-black`}>
      {menus.map((menu) => {
        if (menu.spacer) return <div className="flex-1" />
        const lit = open === menu.id
        const drop =
          lit && menu.items ? (
            <div
              className={`absolute ${menu.right ? 'right-0' : 'left-0'} top-[${menuH - edge}px] w-[${size(menu.w || 200) + edge}px] flex flex-col bg-black pr-[${edge}px] pb-[${edge}px]`}
              onPointerDown={() => {}}
            >
              <div
                className={`flex flex-col w-full max-h-[${Math.max(itemH, height - menuH - size(8))}px] overflow-y-auto py-[${px(2)}] bg-white text-black border-[${edge}px] border-black`}
              >
                {menu.items.map((item) =>
                  item ? (
                    <div
                      className={`flex items-center shrink-0 h-[${itemH}px] pr-[${px(12)}] whitespace-nowrap ${
                        item.dim ? DIM : ''
                      } hover:bg-black hover:text-white`}
                      onClick={item.onClick}
                    >
                      <div className={`flex items-center justify-center shrink-0 w-[${size(18)}px]`}>
                        {item.mark === 'check' ? <Check /> : item.mark === 'diamond' ? <Diamond /> : null}
                      </div>
                      {item.icon ? <div className={`flex shrink-0 mr-[${px(6)}]`}>{item.icon}</div> : null}
                      <span className="flex-1 min-w-0 truncate">{item.label}</span>
                    </div>
                  ) : (
                    <div className={`shrink-0 h-[${edge}px] my-[${px(3)}] bg-[#808080]`} />
                  ),
                )}
              </div>
            </div>
          ) : null
        return (
          <div
            className={`relative flex items-center shrink-0 h-[${menuH - edge}px] px-[${px(8)}] gap-[${px(6)}] whitespace-nowrap ${
              lit ? 'bg-black text-white' : 'active:bg-black active:text-white'
            }`}
            onClick={menu.items ? toggle(menu.id) : menu.onClick}
            onPointerMove={menu.items ? slide(menu.id) : slide(null)}
          >
            {menu.title}
            {drop}
          </div>
        )
      })}
      {corners ? <Corner /> : null}
      {corners ? <Corner right /> : null}
    </div>
  )
}

// ---------------------------------------------------------------- the desktop
//
// What it keeps, in the layout's state (it goes along from scene to scene, and
// is gone at a restart): `wins`, the windows open in the order they were
// opened, each {id, x, y, w, h, z, max, min, snap, shade}, in the desktop's
// pixels (x to h is the window's own box, kept while it fills the desktop or is
// snapped to a half of it, `snap` 'l' or 'r'; `shade` rolled up to its title bar;
// a built-in scene's also its `title`); `boxes`, where each scene's window was
// when it closed, by scene id; `last`, the scene that had the focus at the last
// render; `asked`, the scene this layout last brought forward itself; `gone`, the
// scene whose window was just closed; `menu`, the menu open in the menu bar;
// `picked`, the desktop icon picked; `full`, `peek` and `drag`, a move or a size
// in progress.

const winsOf = (app) => (Array.isArray(app.state.wins) ? app.state.wins : [])
const topZ = (wins) => wins.reduce((z, w) => Math.max(z, w.z || 0), 0)

// What a window's frame takes around its scene: the border, the title bar and its
// rule, and the shadow at its right and bottom.
const chromeW = () => 3 * edge
const chromeH = () => 4 * edge + size(19)
const shadeH = () => 3 * edge + size(19)

function clamp(win, deskW, deskH) {
  const minW = Math.min(deskW, size(160))
  const minH = Math.min(deskH, size(100))
  win.w = Math.round(Math.max(minW, Math.min(win.w, deskW)))
  win.h = Math.round(Math.max(minH, Math.min(win.h, deskH)))
  // A title bar stays where the pointer can get at it.
  const grip = size(48)
  win.x = Math.round(Math.max(grip - win.w, Math.min(win.x, deskW - grip)))
  win.y = Math.round(Math.max(0, Math.min(win.y, deskH - size(19))))
  return win
}

const boxesOf = (app) => (app.state.boxes && typeof app.state.boxes === 'object' ? app.state.boxes : {})

// A closed window's box, for when its scene opens again.
function keep(app, win) {
  const { x, y, w, h, max, snap } = win
  frameos.setState('boxes', { ...boxesOf(app), [win.id]: { x, y, w, h, max, snap } })
}

// The scene's own area in a new window: the scene's own size where it says one
// (`windowSize` in app.frame.scenes, its settings.windowSize), else the layout's
// "Window size" (`WxH`, in a desktop's pixels like every size here); null for the
// whole desktop, which "The whole desktop" keeps for every scene.
function ownSize(app, id) {
  const layout = String(app.state.windowSize || '800x480')
  const scene = layout !== 'max' && Array.isArray(app.frame.scenes) ? app.frame.scenes.find((s) => s.id === id) : null
  const mine = scene ? /^(\d+)x(\d+)$/.exec(String(scene.windowSize || '')) : null
  const m = mine || /^(\d+)x(\d+)$/.exec(layout)
  return m ? { w: size(Number(m[1])), h: size(Number(m[2])), own: !!mine } : null
}

// Where the nth window cascades to: down and right from the top left.
function cascade(n, w, h, deskW, deskH) {
  const step = size(22) * (n % 6)
  return { x: Math.min(size(24) + step, deskW - w), y: Math.min(size(12) + step, deskH - h) }
}

function placed(app, id, wins, deskW, deskH) {
  const win = { id, z: topZ(wins) + 1 }
  // Where it was when it closed, if it was open before.
  const kept = boxesOf(app)[id]
  if (kept) return clamp({ ...kept, ...win }, deskW, deskH)
  // Otherwise the layout's size, its frame around it, cascading from the corner
  // and all of it on the desktop.
  const own = ownSize(app, id)
  // A scene's own size that does not fit is made smaller, its shape kept, once
  // another window is open: the first one still fills the desktop, below.
  const room = own && own.own ? Math.min((deskW - (chromeW())) / own.w, (deskH - (chromeH())) / own.h) : 1
  const shrink = room >= 1 || !wins.some((other) => !other.min) ? 1 : 0.85 * room
  const w = own ? Math.round(own.w * shrink) + chromeW() : deskW + 1
  const h = own ? Math.round(own.h * shrink) + chromeH() : deskH + 1
  if (w <= deskW && h <= deskH) {
    return clamp({ ...win, ...cascade(wins.length, w, h, deskW, deskH), w, h, max: false }, deskW, deskH)
  }
  // Where it does not fit, the first window fills the desktop, which is what the
  // frame looked like before anything else was opened, and the next ones take
  // most of it; set to the whole desktop, every one fills it.
  const shown = wins.filter((other) => !other.min).length
  const step = size(22) * (wins.length % 6)
  const box = { x: size(24) + step, y: size(12) + step, w: deskW * 0.62, h: deskH * 0.62 }
  return clamp({ ...win, ...box, max: !own || shown === 0 }, deskW, deskH)
}

// Where each window is, for a desktop chosen in this one's place (`openPlaces`,
// handed over with `openScenes`): by scene id, its box as a share of the whole
// picture, so a desktop whose bars are elsewhere puts it where it was on the glass.
const share = (v) => Math.round(v * 10000) / 10000
function keepPlaces(app, wins, desk, width, height) {
  const places = {}
  for (const w of wins)
    places[w.id] = {
      x: share((desk.x + w.x) / width), y: share((desk.y + w.y) / height),
      w: share(w.w / width), h: share(w.h / height),
      max: !!w.max, snap: w.snap || null, min: !!w.min,
    }
  if (JSON.stringify(places) !== JSON.stringify(app.state.openPlaces || {})) frameos.setState('openPlaces', places)
}
function carriedPlace(app, id, desk, width, height) {
  const p = app.state.openPlaces && app.state.openPlaces[id]
  if (!p || ![p.x, p.y, p.w, p.h].every((v) => typeof v === 'number' && isFinite(v))) return null
  const snap = p.snap === 'l' || p.snap === 'r' ? p.snap : undefined
  return { x: p.x * width - desk.x, y: p.y * height - desk.y, w: p.w * width, h: p.h * height, max: p.max === true, snap, min: p.min === true }
}

// What another desktop had open when this layout was chosen in its place (its
// `openScenes`, handed over by the runtime: docs/scene-layouts.md "Windows"): a
// window each, where it was there (`openPlaces`), or cascading in that order, so
// the one that had the focus is on top.
function opened(app, names, titleOf, deskW, deskH, desk, width, height) {
  const wins = []
  for (const id of Array.isArray(app.state.openScenes) ? app.state.openScenes : []) {
    if (typeof id !== 'string' || wins.some((w) => w.id === id) || !(names[id] || isSystem(id))) continue
    const there = carriedPlace(app, id, desk, width, height)
    const win = there ? clamp({ ...there, id, z: topZ(wins) + 1 }, deskW, deskH) : placed(app, id, wins, deskW, deskH)
    if (isSystem(id)) win.title = titleOf(id, names)
    wins.push(win)
  }
  return wins
}

// What is open, the one with the focus last: what a layout chosen in this one's
// place opens (`openScenes`).
function keepOpen(app, wins, current) {
  const order = wins
    .filter((w) => w.id !== current)
    .sort((a, b) => (a.z || 0) - (b.z || 0))
    .map((w) => w.id)
  if (wins.some((w) => w.id === current)) order.push(current)
  if (JSON.stringify(order) !== JSON.stringify(app.state.openScenes || [])) frameos.setState('openScenes', order)
}

// Where a window is drawn: its own box, the whole desktop, or a half of it.
function boxOf(win, deskW, deskH) {
  const half = Math.round(deskW / 2)
  if (win.max) return { x: 0, y: 0, w: deskW, h: deskH }
  if (win.snap === 'l') return { x: 0, y: 0, w: half, h: deskH }
  if (win.snap === 'r') return { x: half, y: 0, w: deskW - half, h: deskH }
  return { x: win.x, y: win.y, w: win.w, h: win.h }
}

// What a press, a key or a menu does to the windows. Each one reads the state
// afresh: a drag's moves come faster than renders.
function actions(app) {
  const current = app.frame.sceneId
  const update = (id, change) => {
    const next = winsOf(app).map((w) => (w.id === id ? { ...w, ...change(w) } : w))
    frameos.setState('wins', next)
  }
  // Every window this layout brings forward goes through here, so a built-in
  // scene that loses the focus some other way is known to have gone back.
  const go = (id) => {
    frameos.setState('asked', id)
    frameos.dispatch('setCurrentScene', { sceneId: id })
  }
  const focus = (id) => {
    frameos.setState('menu', null)
    update(id, () => ({ min: false, shade: false }))
    if (id !== current) go(id)
  }
  const open = (id) => {
    frameos.setState('menu', null)
    if (winsOf(app).some((w) => w.id === id)) return focus(id)
    if (id !== current) go(id)
    else if (app.state.gone === id) frameos.setState('gone', null)
  }
  // Read when a handler runs, not when it was drawn: a press before it may have
  // brought another window forward.
  const showing = () => app.frame.sceneId
  const windowOf = (id) => winsOf(app).find((w) => w.id === id)
  // The scene window on top: what Get Info is for, and what a built-in scene
  // opens over.
  const topScene = () =>
    winsOf(app)
      .filter((w) => !isSystem(w.id) && !w.min && !w.shade)
      .sort((a, b) => (b.z || 0) - (a.z || 0))[0]
  // A built-in scene opens over a scene. Over another built-in one, that one stays
  // open in its window, and the scene window on top comes forward to open it over;
  // with none, the built-in one goes back where it came from. Either way the
  // focus is this layout's doing (`asked`): the one left open keeps its window.
  const overAScene = () => {
    const now = showing()
    if (!isSystem(now)) return
    const top = topScene()
    if (top) go(top.id)
    else frameos.dispatch(commandOf(now))
  }
  // A scene's settings, from the gear box on its title bar or Get Info: a window
  // of their own, opened over the scene's window brought forward first; open
  // already, that window comes forward as it was left.
  const sceneSettings = (id) => {
    frameos.setState('menu', null)
    if (windowOf(settingsOf(id))) return focus(settingsOf(id))
    if (id !== showing()) go(id)
    frameos.dispatch('sceneSettings', {})
    frameos.setState('asked', settingsOf(id))
  }
  // File's Get Info: the scene in front's, or the one on top under a built-in
  // scene's window.
  const frontSettings = () => {
    const now = showing()
    const id = isSystem(now) ? (topScene() || {}).id : now
    if (id) sceneSettings(id)
    else frameos.setState('menu', null)
  }
  // A built-in scene of the frame's, one window each: Control Panels (the frame's
  // page: About This Frame, the clock, the disk) and the scene list. Open
  // already, it comes forward as it was left.
  const builtIn = (id, command, payload) => () => {
    frameos.setState('menu', null)
    frameos.setState('picked', null)
    if (windowOf(id)) return focus(id)
    overAScene()
    frameos.dispatch(command, payload)
    frameos.setState('asked', id)
  }
  const controlPanel = builtIn(SETTINGS, 'sceneSettings', { page: 'frame' })
  const sceneList = builtIn(SWITCHER, 'sceneSwitcher', {})
  // The window in front went away: the next one down takes the focus.
  const nextAfter = (id) =>
    winsOf(app)
      .filter((w) => w.id !== id && !w.min && !w.shade)
      .sort((a, b) => (b.z || 0) - (a.z || 0))[0]
  const minimize = (id) => {
    frameos.setState('menu', null)
    update(id, () => ({ min: true }))
    const next = id === current ? nextAfter(id) : null
    if (next) go(next.id)
  }
  // WindowShade: rolled up to its title bar, the next window takes the focus;
  // rolled down, it takes it back.
  const toggleShade = (id) => {
    frameos.setState('menu', null)
    const win = windowOf(id)
    if (!win) return
    if (win.shade) return focus(id)
    update(id, () => ({ shade: true }))
    const next = id === current ? nextAfter(id) : null
    if (next) go(next.id)
  }
  // The Application menu's Hide Others and Show All.
  const hideOthers = () => {
    frameos.setState('menu', null)
    const front = showing()
    frameos.setState('wins', winsOf(app).map((w) => (w.id === front ? w : { ...w, min: true })))
  }
  const showAll = () => {
    frameos.setState('menu', null)
    frameos.setState('wins', winsOf(app).map((w) => ({ ...w, min: false })))
  }
  // A built-in scene with the focus closes as its own Cancel does, back to the
  // scene it was opened over.
  const close = (id) => {
    frameos.setState('menu', null)
    const next = id === current ? nextAfter(id) : null
    const win = winsOf(app).find((w) => w.id === id)
    if (win) keep(app, win)
    frameos.setState('wins', winsOf(app).filter((w) => w.id !== id))
    if (id !== current) return
    frameos.setState('gone', id)
    frameos.setState('full', false)
    if (isSystem(id)) frameos.dispatch(commandOf(id))
    else if (next) go(next.id)
  }
  const toggleMax = (id) => {
    frameos.setState('menu', null)
    update(id, (w) => ({ max: !w.max, snap: null }))
  }
  const toggleFull = () => {
    frameos.setState('menu', null)
    frameos.setState('peek', false)
    frameos.setState('full', !on(app.state.full))
  }
  // Alt+Tab: the window that had the focus before this one, so twice comes back;
  // with Shift, the one at the bottom, so every window comes round in turn.
  const cycle = (back) => {
    const others = winsOf(app)
      .filter((w) => w.id !== current)
      .sort((a, b) => (b.z || 0) - (a.z || 0))
    const next = back ? others[others.length - 1] : others[0]
    if (next) focus(next.id)
    return !!next
  }
  return {
    update, focus, open, sceneSettings, frontSettings, controlPanel, sceneList, minimize, toggleShade, hideOthers,
    showAll, close, toggleMax, toggleFull, cycle,
  }
}

// What a built-in scene's window is called before it has shown its page here.
const titleOf = (id, names) => {
  const scene = settingsFor(id)
  if (scene) return `${names[scene] || scene} Info`
  return id === SWITCHER ? 'Scenes' : 'Control Panels'
}

// What a built-in scene's window is called, by the page it shows.
function systemTitle(app, names) {
  const scene = settingsFor(app.frame.sceneId)
  if (scene) return `${names[scene] || app.state.openedOver || scene} Info`
  if (app.frame.sceneId === SWITCHER) return 'Scenes'
  const page = app.frame.sceneName
  if (page === 'Frame settings') return 'Control Panels'
  if (page === 'Layout settings') return 'Desktop'
  return app.state.openedOver ? `${app.state.openedOver} Info` : 'Settings'
}

function desktop(app, now, width, height) {
  const scale = app.frame.scale || 1
  const builtIn = app.frame.systemScene === true
  const current = app.frame.sceneId
  const names = {}
  for (const scene of app.frame.scenes) names[scene.id] = scene.name || scene.id
  if (!builtIn && current && !names[current]) names[current] = app.frame.sceneName || current
  const store = storeOf(app)
  const assets = assetsOf(app)
  const terminal = terminalOf(app)
  const programs = app.frame.scenes.filter((scene) => !isFrameApp(scene))
  const menuH = size(20)
  const deskTop = menuH
  const deskW = width
  const deskH = Math.max(1, height - menuH)

  // Whatever brought a scene forward (a window, a menu, an icon, the scene list, a
  // button, the API), its window is open and on top, and the one it took the
  // focus from is next below it. A built-in scene's window is named by what it
  // shows while it has the focus, and closes once it has gone back by itself: the
  // focus left it for a scene, and not because this layout moved it. One that
  // opened another (the gear in a scene's settings opening Control Panels) did
  // not go back, and stays open.
  // A layout just chosen in another desktop's place has no windows of its own yet:
  // it opens what that one had open.
  const fresh = !Array.isArray(app.state.wins)
  const saved = fresh ? opened(app, names, titleOf, deskW, deskH, { x: 0, y: deskTop }, width, height) : winsOf(app)
  const wins = saved.filter((w) => w && (names[w.id] || isSystem(w.id)))
  let changed = fresh ? wins.length > 0 : wins.length !== saved.length
  if (current) {
    let win = wins.find((w) => w.id === current)
    if (!win && app.state.gone !== current) {
      win = placed(app, current, wins, deskW, deskH)
      wins.push(win)
      changed = true
    }
    if (win && builtIn && win.title !== systemTitle(app, names)) {
      win.title = systemTitle(app, names)
      changed = true
    }
    if (app.state.last !== current) {
      if (win && (win.min || win.shade)) {
        win.min = false
        win.shade = false
      }
      const before = wins.find((w) => w.id === app.state.last)
      if (before && isSystem(before.id) && !isSystem(current) && app.state.asked !== current) {
        keep(app, before)
        wins.splice(wins.indexOf(before), 1)
      } else if (before) before.z = topZ(wins) + 1
      if (app.state.gone && app.state.gone !== current) frameos.setState('gone', null)
      if (app.state.asked) frameos.setState('asked', null)
      frameos.setState('last', current)
      changed = true
    }
  }
  // Where only so many scenes run at once (app.frame.windows, an ESP32's few),
  // one more closes the one that had the focus longest ago, its box kept.
  const most = app.frame.windows
  if (most > 0) {
    const others = wins.filter((w) => !isSystem(w.id) && w.id !== current).sort((a, b) => (a.z || 0) - (b.z || 0))
    const room = most - (current && !isSystem(current) && wins.some((w) => w.id === current) ? 1 : 0)
    const gone = others.slice(0, Math.max(0, others.length - room))
    if (gone.length) {
      const boxes = { ...boxesOf(app) }
      for (const win of gone) {
        const { x, y, w, h, max, snap } = win
        boxes[win.id] = { x, y, w, h, max, snap }
        wins.splice(wins.indexOf(win), 1)
      }
      frameos.setState('boxes', boxes)
      changed = true
    }
  }
  if (changed) frameos.setState('wins', wins)
  keepOpen(app, wins, current)
  keepPlaces(app, wins, { x: 0, y: deskTop }, width, height)
  for (const win of wins) if (isSystem(win.id)) names[win.id] = win.title || titleOf(win.id, names)

  const focused = wins.find((w) => w.id === current && !w.min && !w.shade)
  const full = !!focused && on(app.state.full)
  const menu = app.state.menu || null
  const {
    update, focus, open, sceneSettings, frontSettings, controlPanel, sceneList, minimize, toggleShade, hideOthers,
    showAll, close, toggleMax, toggleFull,
  } = actions(app)

  // A press on a title bar moves the window, one on its edge sizes it from that
  // edge; the moves that follow are captured by what was pressed. Let go at the
  // top of the desktop, a moved window fills it, at the left or right edge it
  // takes that half; dragged away again, it has its own size back. A rolled-up
  // window only comes to the top: a double click rolls it down.
  const startDrag = (drawn, mode) => (e) => {
    // As it is now, not as it was drawn: a size may have come since.
    const win = winsOf(app).find((w) => w.id === drawn.id) || drawn
    const box = boxOf(win, deskW, deskH)
    const docked = !!(win.max || win.snap)
    // A half sized from its edge is a window of that size from then on.
    if (docked && mode !== 'move') update(win.id, () => ({ ...box, snap: null }))
    frameos.setState('drag', {
      id: win.id,
      mode,
      x: e.x,
      y: e.y,
      from: box,
      own: { w: win.w, h: win.h },
      docked: docked && mode === 'move',
      at: null,
    })
    if (win.shade) update(win.id, () => ({ z: topZ(winsOf(app)) + 1 }))
    else if (win.id !== current) focus(win.id)
  }
  const dragTo = (e) => {
    const drag = app.state.drag
    if (!drag || !e.buttons) return
    const dx = (e.x - drag.x) / scale
    const dy = (e.y - drag.y) / scale
    if (drag.mode === 'move') {
      const x = e.x / scale
      const y = e.y / scale - deskTop
      const at = y <= 2 ? 'max' : x <= 2 ? 'l' : x >= deskW - 3 ? 'r' : null
      if (drag.docked) {
        // A press that does not move leaves it be (a double click rolls it up).
        if (Math.abs(dx) + Math.abs(dy) < 8 * zoom) return
        // Its own size, with the pointer as far across the title bar as it was.
        const across = (drag.x / scale - drag.from.x) / drag.from.w
        const from = { x: drag.x / scale - across * drag.own.w, y: drag.from.y, w: drag.own.w, h: drag.own.h }
        frameos.setState('drag', { ...drag, at, docked: false, from })
        update(drag.id, () => ({ ...clamp({ ...from, x: from.x + dx, y: from.y + dy }, deskW, deskH), max: false, snap: null }))
        return
      }
      if (at !== drag.at) frameos.setState('drag', { ...drag, at })
    }
    const f = drag.from
    update(drag.id, () => {
      const box = { ...f }
      if (drag.mode === 'move') {
        box.x = f.x + dx
        box.y = f.y + dy
      } else {
        if (drag.mode.includes('l')) {
          box.x = Math.min(f.x + dx, f.x + f.w - 80 * zoom)
          box.w = f.w - (box.x - f.x)
        }
        if (drag.mode.includes('r')) box.w = f.w + dx
        if (drag.mode.includes('t')) {
          box.y = Math.max(0, Math.min(f.y + dy, f.y + f.h - 60 * zoom))
          box.h = f.h - (box.y - f.y)
        }
        if (drag.mode.includes('b')) box.h = f.h + dy
      }
      return clamp(box, deskW, deskH)
    })
  }
  const endDrag = () => {
    const drag = app.state.drag
    frameos.setState('drag', null)
    if (drag && drag.mode === 'move' && drag.at && !drag.docked) {
      update(drag.id, () => (drag.at === 'max' ? { max: true, snap: null } : { max: false, snap: drag.at }))
    }
  }
  const corner = 14 * zoom
  const edgeOf = (e) => {
    const x = e.localX < corner ? 'l' : e.localX > e.width - corner ? 'r' : ''
    const y = e.localY < corner ? 't' : e.localY > e.height - corner ? 'b' : ''
    return y + x || 'b'
  }
  const sizing = (win) => ({
    onPointerDown: (e) => startDrag(win, edgeOf(e))(e),
    onPointerMove: dragTo,
    onPointerUp: endDrag,
  })
  const moving = (win) => ({
    onPointerDown: startDrag(win, 'move'),
    onPointerMove: dragTo,
    onPointerUp: endDrag,
    onDoubleClick: () => toggleShade(win.id),
  })

  // A window: a black line around it and a shadow at its right and bottom (the
  // black under it, showing past its edge), the title bar and a rule, and the
  // scene. Rolled up, the title bar alone.
  const windowOf = (win) => {
    const active = win.id === current && !win.shade
    const box = boxOf(win, deskW, deskH)
    const h = win.shade ? shadeH() : box.h
    return (
      <div
        className={`absolute left-[${box.x}px] top-[${box.y}px] w-[${box.w}px] h-[${h}px] flex flex-col bg-black pr-[${edge}px] pb-[${edge}px]`}
        {...(win.max || win.shade ? {} : sizing(win))}
      >
        <div className={`flex flex-col flex-1 min-h-0 bg-white border-[${edge}px] border-black`}>
          <TitleBar
            title={names[win.id]}
            active={active}
            onClose={() => close(win.id)}
            onZoom={() => toggleMax(win.id)}
            onSettings={isSystem(win.id) ? undefined : () => sceneSettings(win.id)}
            drag={moving(win)}
          />
          {win.shade ? null : <div className={`shrink-0 h-[${edge}px] bg-black`} />}
          {win.shade ? null : (
            <div className="relative flex flex-col flex-1 min-h-0">
              {active ? <yield /> : <Scene id={win.id} />}
              {/* A press on a window behind brings it forward, and is only that. */}
              {active ? null : <div className="absolute inset-0" onPointerDown={() => focus(win.id)} />}
            </div>
          )}
        </div>
      </div>
    )
  }

  // Where a window let go now would go: a grey outline over the windows.
  const outline = () => {
    const drag = app.state.drag
    if (!drag || drag.mode !== 'move' || !drag.at || drag.docked) return null
    const b = boxOf({ max: drag.at === 'max', snap: drag.at }, deskW, deskH)
    const inset = size(3)
    return (
      <div
        className={`absolute left-[${b.x + inset}px] top-[${b.y + inset}px] w-[${b.w - 2 * inset}px] h-[${b.h - 2 * inset}px] border-[${Math.max(2, edge * 2)}px] border-black`}
      />
    )
  }

  // The frame's own apps down the right of the desktop, in columns leftwards: a
  // click picks one, a double click opens it.
  const icons = () => {
    const iconW = size(84)
    const iconH = size(62)
    const perColumn = Math.max(1, Math.floor((deskH - size(8)) / iconH))
    const items = [
      { id: SETTINGS, label: 'Frame', Icon: DiskIcon, go: controlPanel },
      { id: SWITCHER, label: 'Scenes', Icon: FolderIcon, go: sceneList },
      ...(store ? [{ id: store.id, label: names[store.id], Icon: StoreIcon, go: () => open(store.id) }] : []),
      ...(assets ? [{ id: assets.id, label: names[assets.id], Icon: AssetsIcon, go: () => open(assets.id) }] : []),
      ...(terminal ? [{ id: terminal.id, label: names[terminal.id], Icon: TerminalIcon, go: () => open(terminal.id) }] : []),
    ]
    return items.map((item, i) => {
      const x = deskW - size(4) - (Math.floor(i / perColumn) + 1) * iconW
      const y = size(10) + (i % perColumn) * iconH
      const picked = app.state.picked === item.id
      const Icon = item.Icon
      return (
        <div
          className={`absolute left-[${x}px] top-[${y}px] w-[${iconW}px] h-[${iconH}px] flex flex-col items-center gap-[${px(3)}]`}
          onClick={() => frameos.setState('picked', item.id)}
          onDoubleClick={() => (frameos.setState('picked', null), item.go())}
        >
          <Icon ink={picked ? '#ffffff' : '#000000'} paper={picked ? '#000000' : '#ffffff'} />
          <span
            className={`max-w-[${iconW}px] px-[${px(2)}] truncate text-[${px(12)}] ${picked ? 'bg-black text-white' : 'bg-white text-black'}`}
          >
            {item.label}
          </span>
        </div>
      )
    })
  }

  // The menu bar: the mark's menu, File, Scenes and Special, the clock and the
  // Application menu at the right end.
  const isOpen = (id) => wins.some((w) => w.id === id)
  const frontId = focused ? focused.id : current
  const appsHere = [store, assets, terminal].filter(Boolean)
  const menus = [
    {
      id: 'mark',
      title: <Mark />,
      w: 210,
      items: [
        { label: 'About This Frame…', onClick: controlPanel },
        null,
        ...appsHere.map((scene) => ({ label: names[scene.id], onClick: () => open(scene.id), mark: isOpen(scene.id) ? 'diamond' : null })),
        { label: 'Scenes…', onClick: sceneList },
      ],
    },
    {
      id: 'file',
      title: 'File',
      w: 190,
      items: [
        { label: 'Open Scene…', onClick: sceneList },
        { label: 'Close Window', onClick: () => (focused ? close(focused.id) : frameos.setState('menu', null)), dim: !focused },
        null,
        { label: 'Get Info', onClick: frontSettings },
      ],
    },
    {
      id: 'scenes',
      title: 'Scenes',
      w: 220,
      items: [
        ...programs.map((scene) => ({ label: names[scene.id], onClick: () => open(scene.id), mark: isOpen(scene.id) ? 'diamond' : null })),
        ...(appsHere.length ? [null] : []),
        ...appsHere.map((scene) => ({ label: names[scene.id], onClick: () => open(scene.id), mark: isOpen(scene.id) ? 'diamond' : null })),
      ],
    },
    {
      id: 'special',
      title: 'Special',
      w: 200,
      items: [
        {
          label: 'Clean Up Windows',
          onClick: () => {
            frameos.setState('menu', null)
            // Bottom to top, the window in front last: the one most down and right.
            const all = winsOf(app)
            const order = all
              .slice()
              .sort((a, b) => (a.id === current) - (b.id === current) || (a.z || 0) - (b.z || 0))
              .map((w) => w.id)
            frameos.setState(
              'wins',
              all.map((w) => {
                const at = cascade(order.indexOf(w.id), w.w, w.h, deskW, deskH)
                return clamp({ ...w, ...at, max: false, snap: null }, deskW, deskH)
              }),
            )
          },
        },
        { label: full ? 'Exit Full Screen' : 'Full Screen', onClick: toggleFull, dim: !focused },
      ],
    },
    { spacer: true },
    { id: 'clock', title: clock(now, on(app.state.twentyFourHour)), onClick: controlPanel },
    {
      id: 'app',
      title: <SmallIcon id={frontId} />,
      right: true,
      w: 220,
      items: [
        {
          label: `Hide ${names[frontId] || 'Window'}`,
          onClick: () => (focused ? minimize(focused.id) : frameos.setState('menu', null)),
          dim: !focused,
        },
        { label: 'Hide Others', onClick: hideOthers },
        { label: 'Show All', onClick: showAll },
        null,
        ...wins.map((win) => ({
          label: names[win.id],
          icon: <SmallIcon id={win.id} />,
          onClick: () => focus(win.id),
          mark: win.id === current ? 'check' : null,
          dim: !!win.min,
        })),
      ],
    },
  ]

  const cover = menu ? (
    <div className="absolute inset-0" onPointerDown={() => frameos.setState('menu', null)} onClick={() => {}} />
  ) : null

  if (full) {
    // The panel is the window's. The pointer at the top edge brings the menu bar;
    // moved back over the window, it goes again, unless a menu is open.
    const peek = on(app.state.peek) || !!menu
    return (
      <div className={`relative w-full h-full bg-black text-[${px(13)}]`}>
        <div className="absolute inset-0 flex flex-col">
          <yield />
        </div>
        {!peek ? (
          <div className="absolute left-0 top-0 w-full h-[2px]" onPointerMove={() => frameos.setState('peek', true)} />
        ) : menu ? null : (
          <div
            className={`absolute left-0 top-[${menuH}px] w-full h-[${Math.max(1, height - menuH)}px]`}
            onPointerMove={() => frameos.setState('peek', false)}
          />
        )}
        {cover}
        {peek ? <MenuBar app={app} menus={menus} height={height} /> : null}
      </div>
    )
  }

  const shown = wins.filter((w) => !w.min && !(focused && w.id === focused.id)).sort((a, b) => (a.z || 0) - (b.z || 0))
  if (focused) shown.push(focused)
  return (
    <div className={`relative w-full h-full ${DESKTOP} text-black text-[${px(13)}]`}>
      <div
        className={`absolute left-0 top-[${deskTop}px] w-[${deskW}px] h-[${deskH}px]`}
        onClick={() => frameos.setState('picked', null)}
      >
        {icons()}
        {shown.map(windowOf)}
        {outline()}
      </div>
      {cover}
      <MenuBar app={app} menus={menus} height={height} corners />
    </div>
  )
}

// F11 gives the panel to the window in front and takes it back; Escape closes a
// menu and leaves the full screen; Alt+Tab (or Cmd+Tab) brings the window before
// forward (Shift: the one at the bottom), Alt+F4 or Cmd+W closes the one in front
// and Cmd+H hides it. The scene heard the key first.
export function onEvent(app, context) {
  if (context.event !== 'keyDown' || !Array.isArray(app.frame.scenes) || !windowsOn(app)) return false
  const payload = context.payload || {}
  const key = payload.key
  if (key === 'F11') {
    frameos.setState('peek', false)
    frameos.setState('full', !on(app.state.full))
    return true
  }
  if (key === 'Escape' && (app.state.menu || on(app.state.full))) {
    frameos.setState('menu', null)
    frameos.setState('full', false)
    return true
  }
  const alt = payload.alt === true
  const cmd = payload.meta === true
  if (key === 'Tab' && (alt || cmd)) return actions(app).cycle(payload.shift === true)
  if (!app.frame.sceneId) return false
  if ((key === 'F4' && alt) || ((key === 'w' || key === 'W') && cmd)) {
    actions(app).close(app.frame.sceneId)
    return true
  }
  if ((key === 'h' || key === 'H') && cmd) {
    actions(app).minimize(app.frame.sceneId)
    return true
  }
  return false
}

const windowsOn = (app) => app.state.windows !== false && app.state.windows !== 'false'

export function get(app) {
  // app.frame's size is the panel's over the render scale, before the frame's rotation.
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = turned ? app.frame.height : app.frame.width
  const height = turned ? app.frame.width : app.frame.height
  const shortSide = Math.min(app.frame.width, app.frame.height)
  zoom = shortSide >= (app.frame.paper ? 1000 : 2160) ? 2 : shortSide >= 480 ? 1 : shortSide / 480
  edge = Math.max(1, Math.round(zoom))
  const now = new Date()
  dress(app, THEMES, 'classic')
  // The clock changes on the minute: nothing to draw until then.
  frameos.setNextSleep(60 - now.getSeconds())
  if (Array.isArray(app.frame.scenes) && windowsOn(app)) return desktop(app, now, width, height)
  // One scene at a time: nothing else is open, nothing for another layout to open.
  if (Array.isArray(app.state.openScenes) && app.state.openScenes.length) frameos.setState('openScenes', [])
  const name = app.frame.sceneName || 'FrameOS'
  const builtIn = app.frame.systemScene === true
  const settingsOpen = builtIn && name.includes('settings')
  const frameOpen = settingsOpen && name.startsWith('Frame')
  const listOpen = builtIn && !settingsOpen
  const title = listOpen ? 'Scenes' : frameOpen ? 'Control Panels' : settingsOpen ? 'Settings' : name
  const zoomed = app.state.zoomed === true
  const menuH = size(20)
  // A built-in scene's own command, again, goes back to the scene it opened over.
  const closeBuiltIn = () => frameos.dispatch(settingsOpen ? 'sceneSettings' : 'sceneSwitcher')
  const shut = () => frameos.setState('menu', null)
  const openList = () => (shut(), frameos.dispatch('sceneSwitcher', { swap: true }))
  const openSettings = () => (shut(), frameos.dispatch('sceneSettings'))
  const openFrame = () => (shut(), frameos.dispatch('sceneSettings', { page: 'frame' }))
  const toggleZoom = () => (shut(), frameos.setState('zoomed', !zoomed))
  const menus = [
    {
      id: 'mark',
      title: <Mark />,
      w: 210,
      items: [{ label: 'About This Frame…', onClick: openFrame }, null, { label: 'Scenes…', onClick: openList }],
    },
    {
      id: 'file',
      title: 'File',
      w: 190,
      items: [
        { label: 'Open Scene…', onClick: openList },
        { label: 'Close Window', onClick: builtIn ? () => (shut(), closeBuiltIn()) : openList },
        null,
        { label: 'Get Info', onClick: builtIn ? shut : openSettings, dim: builtIn },
      ],
    },
    { id: 'special', title: 'Special', w: 200, items: [{ label: zoomed ? 'Show Window' : 'Hide Window Frame', onClick: toggleZoom }] },
    { spacer: true },
    { id: 'clock', title: clock(now, on(app.state.twentyFourHour)), onClick: openFrame },
  ]
  const menu = app.state.menu || null
  return (
    <div className={`relative w-full h-full ${DESKTOP} text-black text-[${px(13)}]`}>
      <div className={`absolute left-0 top-[${menuH}px] w-full h-[${Math.max(1, height - menuH)}px] flex flex-col ${zoomed ? '' : `p-[${px(10)}]`}`}>
        {zoomed ? (
          <yield />
        ) : (
          <div className={`flex flex-col flex-1 min-h-0 bg-black pr-[${edge}px] pb-[${edge}px]`}>
            <div className={`flex flex-col flex-1 min-h-0 bg-white border-[${edge}px] border-black`}>
              <TitleBar
                title={title}
                active={true}
                onClose={builtIn ? closeBuiltIn : openList}
                onZoom={toggleZoom}
                onSettings={builtIn ? undefined : openSettings}
                drag={{ onDoubleClick: toggleZoom }}
              />
              <div className={`shrink-0 h-[${edge}px] bg-black`} />
              <div className="flex flex-col flex-1 min-h-0">
                <yield />
              </div>
            </div>
          </div>
        )}
      </div>
      {menu ? <div className="absolute inset-0" onPointerDown={shut} onClick={() => {}} /> : null}
      <MenuBar app={app} menus={menus} height={height} corners />
    </div>
  )
}

