sources.app.tsx:
// A two-panel file commander around the scenes: two blue panels side by side
// (one above the other on a tall screen), each with a double line round it, a
// path at the top and a status line at the bottom, a command line under them
// and the function keys along the bottom. The panel with the focus has its
// path lit; it holds the frame's scene (the <yield />).
//
// On a frame that runs its scenes side by side (app.frame.scenes is there) the
// other panel runs a scene of its own, at once: a press on it, or Tab, gives it
// the focus. Two scenes at most, which every host can run. Elsewhere, and where
// a key turns it so, the other panel is the Info panel: the frame's facts.
//
// The keys, tapped on the bar or pressed: 1 Frame (the frame's page), 2 Scenes
// (the scene list, in the panel with the focus), 3 View (that panel on the
// whole screen, the keys kept; again to go back, or Escape), 4 Setup (its
// scene's settings), 5 Swap (the two panels change places), 6 Next (the next
// scene in that panel), 7 Store, 8 Term and 9 Files (the frame's own apps,
// where it has them) and 10 Info (the other panel's scene or the Info panel).
// The command line opens the terminal where the frame has it, the scene list
// where it does not. Chosen in another desktop's place it opens the two that
// desktop had in front, and hands the next one its two as halves.
const pad = (n) => String(n).padStart(2, '0')
const on = (value) => value === true || value === 'true'
const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']

// The frame's own scenes (the contract's `scenes.settings` and `scenes.switcher`).
const SETTINGS = 'system/sceneSettings'
const SETTINGS_OF = 'system/sceneSettings#'
const settingsFor = (id) => (typeof id === 'string' && id.startsWith(SETTINGS_OF) ? id.slice(SETTINGS_OF.length) : null)
const SWITCHER = 'system/sceneSwitcher'
const isSystem = (id) => typeof id === 'string' && id.startsWith('system/')
// The frame's own apps that are scenes like any other (docs/scene-store.md,
// docs/terminal.md), by their sample's id or their name.
const appIs = (id, name) => (scene) =>
  !!scene && (scene.id === id || String(scene.name || '').trim().toLowerCase() === name)
const isStore = appIs('scene-store', 'scene store')
const isAssets = appIs('asset-browser', 'asset browser')
const isTerminal = appIs('terminal-app', 'terminal')
const isFrameApp = (scene) => isStore(scene) || isAssets(scene) || isTerminal(scene)
const findScene = (app, test) => (Array.isArray(app.frame.scenes) ? app.frame.scenes.find(test) : undefined)

// The frame's own pages in this layout's look (docs/jsx-ui.md "Themes"): the
// layout keeps it in its state as `theme`; not on e-paper but for high contrast.
const CONTRAST = {
  page: 'bg-black text-white',
  bar: 'border-b-2 border-white',
  button: 'font-bold bg-black text-white border-2 border-white active:bg-white active:text-black',
  primary: 'font-bold bg-white text-black border-2 border-white active:bg-black active:text-white',
  selected: 'bg-white text-black border-2 border-white',
  field: 'bg-black text-white border-2 border-white placeholder:text-white focus:border-[#ffff00]',
  option: 'active:bg-white active:text-black',
  picked: 'bg-white text-black',
  switch: 'rounded-full border-2 border-white',
  switchOn: 'rounded-full bg-white border-2 border-white',
  knob: 'rounded-full bg-white',
  knobOn: 'rounded-full bg-black',
  muted: 'text-white',
  card: 'border-2 border-white',
  tile: 'bg-black text-white border-2 border-white active:bg-white active:text-black',
  tileLit: 'bg-black text-white border-4 border-[#ffff00]',
  accent: 'bg-[#ffff00]',
  keyboard: 'bg-black text-white border-t-2 border-white',
  key: 'bg-black text-white border-2 border-white active:bg-white active:text-black',
  keyMod: 'bg-black text-[#ffff00] border-2 border-white active:bg-white active:text-black',
  keyLit: 'bg-white text-black border-2 border-white',
}

const THEMES = {
  commander: {
    page: 'bg-[#0000aa] text-[#55ffff]',
    bar: 'border-b-1 border-[#55ffff]',
    button: 'bg-[#00aaaa] text-black active:bg-[#55ffff]',
    primary: 'bg-[#aaaaaa] text-black active:bg-white',
    selected: 'bg-[#55ffff] text-black',
    field: 'bg-black text-[#aaaaaa] border-1 border-[#55ffff] focus:border-[#ffff55] placeholder:text-[#555555]',
    option: 'active:bg-[#00aaaa] active:text-black',
    picked: 'bg-[#00aaaa] text-black',
    switch: 'border-1 border-[#55ffff]',
    switchOn: 'bg-[#00aaaa] border-1 border-[#55ffff]',
    knob: 'bg-[#55ffff]',
    knobOn: 'bg-[#0000aa]',
    muted: 'text-[#00aaaa]',
    card: 'border-1 border-[#55ffff]',
    tile: 'bg-[#0000aa] text-[#55ffff] border-1 border-[#55ffff] active:bg-[#00aaaa] active:text-black',
    tileLit: 'bg-[#00aaaa] text-black border-1 border-[#55ffff]',
    accent: 'bg-[#ffff55]',
    keyboard: 'bg-black text-[#aaaaaa]',
    key: 'bg-[#00aaaa] text-black active:bg-[#55ffff]',
    keyMod: 'bg-[#aaaaaa] text-black active:bg-white',
    keyLit: 'bg-[#55ffff] text-black',
  },
}

function dress(app, themes, fallback) {
  const name = String(app.state.look || fallback)
  const theme = name === 'contrast' ? CONTRAST : app.frame.paper ? null : themes[name] || null
  const key = theme ? name : ''
  if ((app.state.themeOf || '') === key) return
  frameos.setState('theme', theme)
  frameos.setState('themeOf', key)
}

// The colors: a commander's own on a screen; on color e-paper, which has blue
// but no cyan, white lines on blue; black on white on a panel without color.
const SCREEN = {
  screen: '#000000', panel: '#0000aa', line: '#55ffff', text: '#55ffff', bright: '#ffffff', yellow: '#ffff55',
  lit: '#00aaaa', litText: '#000000', prompt: '#aaaaaa', keyNum: '#ffffff', keyText: '#000000', keyBg: '#00aaaa',
}
const PAPER = { ...SCREEN, line: '#ffffff', text: '#ffffff', lit: '#ffffff', keyBg: '#ffffff', prompt: '#ffffff' }
const MONO = {
  screen: '#ffffff', panel: '#ffffff', line: '#000000', text: '#000000', bright: '#000000', yellow: '#000000',
  lit: '#000000', litText: '#ffffff', prompt: '#000000', keyNum: '#000000', keyText: '#ffffff', keyBg: '#000000',
}
let c = SCREEN

// Sizes are pixels of the screen's own: twice that from a short side of 2160 (a
// 4K screen), or of 1000 on e-paper, and in proportion under 480.
let zoom = 1
let edge = 1
const px = (n) => `${Math.round(n * zoom * 10) / 10}px`

// A scene's name as DOS would have it: eight letters, a tilde where it was longer.
function dosName(name) {
  const letters = String(name || '').toUpperCase().replace(/[^A-Z0-9]+/g, '')
  if (!letters) return 'SCENE'
  return letters.length > 8 ? `${letters.slice(0, 6)}~1` : letters
}

// The path a panel shows at its top.
function pathOf(id, names) {
  if (id === SWITCHER) return 'C:\\SCENES'
  if (id === SETTINGS) return 'C:\\FRAME'
  const of = settingsFor(id)
  if (of) return `C:\\SCENES\\${dosName(names[of] || of)}\\SETUP`
  return `C:\\SCENES\\${dosName(names[id] || id)}`
}

function clock(now) {
  return `${pad(now.getHours())}:${pad(now.getMinutes())}`
}

// One panel: a double line round it, its path at the top (lit where it has the
// focus), what it holds, and a status line under a single rule.
function Panel({ path, lit, status, onPath, children }) {
  return (
    <div className={`relative flex flex-col flex-1 basis-0 min-w-0 min-h-0 bg-[${c.panel}] p-[${px(2)}]`}>
      <div className={`flex flex-col flex-1 min-h-0 border-[${edge}px] border-[${c.line}] p-[${px(2)}]`}>
        {/* The path above it is 16 px from the top: the scene starts below it, or
            the path would be painted over it and the scene drawn as a picture. */}
        <div className={`flex flex-col flex-1 min-h-0 border-[${edge}px] border-[${c.line}] pt-[${px(12)}] px-[${px(3)}]`}>
          <div className="relative flex flex-col flex-1 min-h-0">{children}</div>
          <div className={`shrink-0 h-[${edge}px] mt-[${px(3)}] bg-[${c.line}]`} />
          <div className={`flex items-center shrink-0 h-[${px(20)}] gap-[${px(8)}] text-[${c.text}]`}>
            <span className="flex-1 min-w-0 truncate">{status[0]}</span>
            <span className="shrink-0 whitespace-nowrap">{status[1]}</span>
          </div>
        </div>
      </div>
      <div className={`absolute left-0 top-0 w-full h-[${px(16)}] flex justify-center`}>
        <div
          className={`flex items-center h-[${px(16)}] max-w-[80%] px-[${px(6)}] ${lit ? `bg-[${c.lit}] text-[${c.litText}]` : `bg-[${c.panel}] text-[${c.text}]`}`}
          onClick={onPath}
        >
          <span className="truncate leading-[1]">{path}</span>
        </div>
      </div>
    </div>
  )
}

// The Info panel: what the frame knows of itself.
function Info({ app, now, count, showing }) {
  const lines = [
    ...(showing ? [[showing, 'showing']] : []),
    [clock(now), 'time'],
    [`${Math.round(app.frame.width)} x ${Math.round(app.frame.height)}`, app.frame.paper ? 'e-paper' : 'screen'],
    ...(typeof app.frame.batteryPercent === 'number' ? [[`${app.frame.batteryPercent}%`, 'battery']] : []),
    ...(typeof app.frame.wifiRssi === 'number' ? [[`${app.frame.wifiRssi} dBm`, 'Wi-Fi']] : []),
    ...(count ? [[String(count), count === 1 ? 'scene' : 'scenes']] : []),
  ]
  return (
    <div className={`flex flex-col flex-1 min-h-0 items-center gap-[${px(6)}] pt-[${px(10)}] text-[${c.text}] overflow-hidden`}>
      <span className={`font-bold text-[${c.yellow}]`}>FrameOS Commander</span>
      <span>{`${DAYS[now.getDay()]}, ${now.getDate()} ${MONTHS[now.getMonth()]} ${now.getFullYear()}`}</span>
      <div className={`w-[60%] h-[${edge}px] bg-[${c.line}]`} />
      {lines.map(([value, what]) => (
        <div className={`flex w-[70%] gap-[${px(8)}]`}>
          <span className={`flex-1 min-w-0 truncate text-[${c.bright}]`}>{value}</span>
          <span className="shrink-0">{what}</span>
        </div>
      ))}
    </div>
  )
}

// What the panels hold, in the layout's state: `panels`, the two scenes [left,
// right] (null for the Info panel), `side`, the one with the focus, `under`, the
// scene a built-in one opened over in each, `hidden`, the scene the Info panel
// took the place of, and `view`, the panel with the focus on the whole screen.
// Read afresh by every handler: a key may have moved them since the render.
function panelsOf(app) {
  const p = app.state.panels
  return Array.isArray(p) && p.length === 2 ? [p[0] || null, p[1] || null] : [null, null]
}

function actions(app, programs) {
  const showing = () => app.frame.sceneId
  const sideOf = () => (app.state.side === 1 ? 1 : 0)
  const go = (id) => {
    if (id && id !== showing()) frameos.dispatch('setCurrentScene', { sceneId: id })
  }
  // The other panel's scene takes the focus, where it has one.
  const other = () => {
    const panels = panelsOf(app)
    const there = panels[1 - sideOf()]
    if (there && !isSystem(there)) go(there)
    return !!there
  }
  const swap = () => {
    const panels = panelsOf(app)
    frameos.setState('panels', [panels[1], panels[0]])
    frameos.setState('side', 1 - sideOf())
    const under = Array.isArray(app.state.under) ? app.state.under : [null, null]
    frameos.setState('under', [under[1] || null, under[0] || null])
  }
  // The next of the frame's scenes in the panel with the focus, past the one in
  // the other panel.
  const next = () => {
    const panels = panelsOf(app)
    const there = panels[1 - sideOf()]
    const ids = programs.map((scene) => scene.id).filter((id) => id !== there)
    if (!ids.length) return
    const at = ids.indexOf(showing())
    go(ids[(at + 1) % ids.length])
  }
  // The other panel: its scene or the Info panel, back and forth.
  const info = () => {
    const panels = panelsOf(app)
    const side = sideOf()
    const there = panels[1 - side]
    if (there) {
      frameos.setState('hidden', there)
    } else {
      const back = app.state.hidden
      const ids = programs.map((scene) => scene.id).filter((id) => id !== panels[side])
      panels[1 - side] = ids.includes(back) ? back : ids[0] || null
      frameos.setState('hidden', null)
    }
    if (there) panels[1 - side] = null
    frameos.setState('panels', panels)
  }
  const view = () => frameos.setState('view', !on(app.state.view))
  const frame = () => frameos.dispatch('sceneSettings', { page: 'frame' })
  const sceneList = () => frameos.dispatch('sceneSwitcher')
  const setup = () => {
    if (!isSystem(showing())) frameos.dispatch('sceneSettings', {})
  }
  return { other, swap, next, info, view, frame, sceneList, setup, go }
}

// The function keys: what each is called and does, blank where the frame has
// nothing for it.
function keysOf(app, act) {
  const store = findScene(app, isStore)
  const terminal = findScene(app, isTerminal)
  const assets = findScene(app, isAssets)
  const desk = Array.isArray(app.frame.scenes) && windowsOn(app)
  return [
    ['Frame', act.frame],
    ['Scenes', act.sceneList],
    ['View', act.view],
    ['Setup', act.setup],
    desk ? ['Swap', act.swap] : ['', null],
    desk ? ['Next', act.next] : ['', null],
    store ? ['Store', () => act.go(store.id)] : ['', null],
    terminal ? ['Term', () => act.go(terminal.id)] : ['', null],
    assets ? ['Files', () => act.go(assets.id)] : ['', null],
    desk ? ['Info', act.info] : ['', null],
  ]
}

const windowsOn = (app) => app.state.windows !== false && app.state.windows !== 'false'

// The panels' scenes for this render, from what they held and the scene showing:
// a scene brought forward that neither panel holds goes into the one with the
// focus, and a built-in scene that lost the focus gives its panel back to the
// scene it opened over.
function arrange(app, names, programs) {
  const current = app.frame.sceneId
  const valid = (id) => !!id && (!!names[id] || isSystem(id))
  let panels = panelsOf(app).map((id) => (valid(id) ? id : null))
  let under = Array.isArray(app.state.under) ? [app.state.under[0] || null, app.state.under[1] || null] : [null, null]
  let side = app.state.side === 1 ? 1 : 0
  if (!Array.isArray(app.state.panels)) {
    // Fresh: the two another desktop had in front (`openScenes`, the one with
    // the focus last), else the scene showing and the next of the frame's.
    const carried = (Array.isArray(app.state.openScenes) ? app.state.openScenes : []).filter(
      (id) => typeof id === 'string' && names[id] && id !== current,
    )
    const ids = programs.map((scene) => scene.id)
    const at = ids.indexOf(current)
    const following = ids.length > 1 ? ids[(at + 1) % ids.length] : null
    const second = carried.length ? carried[carried.length - 1] : following !== current ? following : null
    const place = app.state.openPlaces && second ? app.state.openPlaces[second] : null
    // Where the other desktop had it on the right of the scene showing, it goes right.
    const right = !place || typeof place.x !== 'number' || place.x >= 0.25
    panels = right ? [current || null, second] : [second, current || null]
    side = right ? 0 : 1
  }
  if (current) {
    const at = panels.indexOf(current)
    if (at >= 0) side = at
    else {
      if (!isSystem(current)) under[side] = null
      else if (panels[side] && !isSystem(panels[side])) under[side] = panels[side]
      panels[side] = current
    }
  }
  const away = 1 - side
  if (panels[away] && isSystem(panels[away])) {
    panels[away] = under[away] && under[away] !== panels[side] ? under[away] : null
    under[away] = null
  }
  // Where only one scene runs at a time, the other panel is the Info panel.
  if (app.frame.windows > 0 && app.frame.windows < 2) panels[away] = null
  if (JSON.stringify(panels) !== JSON.stringify(app.state.panels || null)) frameos.setState('panels', panels)
  if (side !== (app.state.side === 1 ? 1 : 0)) frameos.setState('side', side)
  if (JSON.stringify(under) !== JSON.stringify(app.state.under || [null, null])) frameos.setState('under', under)
  return { panels, side }
}

// What a layout chosen in this one's place opens (`openScenes`, the one with the
// focus last) and where (`openPlaces`, halves of the screen).
function handOver(app, panels, side, stacked) {
  const order = [panels[1 - side], panels[side]].filter((id) => id && !isSystem(id))
  if (JSON.stringify(order) !== JSON.stringify(app.state.openScenes || [])) frameos.setState('openScenes', order)
  const places = {}
  panels.forEach((id, i) => {
    if (!id || isSystem(id)) return
    places[id] = stacked
      ? { x: 0, y: i * 0.45, w: 1, h: 0.45, max: false, snap: null, min: false }
      : { x: i * 0.5, y: 0, w: 0.5, h: 0.9, max: false, snap: i ? 'r' : 'l', min: false }
  })
  if (JSON.stringify(places) !== JSON.stringify(app.state.openPlaces || {})) frameos.setState('openPlaces', places)
}

export function onEvent(app, context) {
  if (context.event !== 'keyDown') return false
  const payload = context.payload || {}
  const key = payload.key
  const desk = Array.isArray(app.frame.scenes) && windowsOn(app)
  const programs = desk ? app.frame.scenes.filter((scene) => !isFrameApp(scene)) : []
  const act = actions(app, programs)
  if (key === 'Escape' && on(app.state.view)) {
    frameos.setState('view', false)
    return true
  }
  if (key === 'Tab' && desk && !payload.alt && !payload.meta && !payload.ctrl) return act.other()
  const m = /^F(\d+)$/.exec(String(key || ''))
  if (!m || payload.alt || payload.meta || payload.ctrl) return false
  const entry = keysOf(app, act)[Number(m[1]) - 1]
  if (!entry || !entry[1]) return false
  entry[1]()
  return true
}

export function get(app) {
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = turned ? app.frame.height : app.frame.width
  const height = turned ? app.frame.width : app.frame.height
  const shortSide = Math.min(app.frame.width, app.frame.height)
  zoom = shortSide >= (app.frame.paper ? 1000 : 2160) ? 2 : shortSide >= 480 ? 1 : shortSide / 480
  edge = Math.max(1, Math.round(zoom))
  c = app.frame.color === false ? MONO : app.frame.paper ? PAPER : SCREEN
  dress(app, THEMES, 'commander')
  const now = new Date()
  frameos.setNextSleep(60 - now.getSeconds())

  const current = app.frame.sceneId || ''
  const desk = Array.isArray(app.frame.scenes) && windowsOn(app)
  const names = {}
  if (desk) for (const scene of app.frame.scenes) names[scene.id] = scene.name || scene.id
  if (current && !names[current]) names[current] = app.frame.sceneName || current
  const programs = desk ? app.frame.scenes.filter((scene) => !isFrameApp(scene)) : []
  const act = actions(app, programs)
  const stacked = width < height

  let panels = [current, null]
  let side = 0
  if (desk) {
    const arranged = arrange(app, names, programs)
    panels = arranged.panels
    side = arranged.side
    handOver(app, panels, side, stacked)
  } else if (Array.isArray(app.state.openScenes) && app.state.openScenes.length) {
    // One scene at a time: nothing for another layout to open.
    frameos.setState('openScenes', [])
  }
  const date = `${pad(now.getDate())}-${pad(now.getMonth() + 1)}-${String(now.getFullYear()).slice(2)}`
  const statusOf = (id) =>
    isSystem(id) ? [app.frame.sceneName || 'FRAME', clock(now)] : [`${dosName(names[id] || id)}.SCN`, `${date} ${clock(now)}`]
  const titleOf = (id) => (id === SETTINGS ? 'C:\\FRAME' : pathOf(id, names))

  const panelOf = (i) => {
    const id = panels[i]
    const focused = i === side
    if (!id) {
      return (
        <Panel path="Info" lit={false} status={['FRAMEOS', clock(now)]} onPath={desk ? act.info : undefined}>
          <Info app={app} now={now} count={programs.length} showing={panels[side] ? `${dosName(names[panels[side]] || panels[side])}.SCN` : ''} />
        </Panel>
      )
    }
    return (
      <Panel path={titleOf(id)} lit={focused} status={statusOf(id)} onPath={focused ? act.sceneList : () => act.go(id)}>
        {focused ? <yield /> : <Scene id={id} />}
        {/* A press on the other panel's scene gives it the focus, and is only that. */}
        {focused ? null : <div className="absolute inset-0" onPointerDown={() => act.go(id)} />}
      </Panel>
    )
  }

  const keys = on(app.state.showKeys) ? keysOf(app, act) : null
  // Ten keys across: a smaller face where a key has under 60 pixels.
  const keyText = width / 10 < 60 * zoom ? px(11) : px(14)
  const keyBar = keys ? (
    <div className={`flex shrink-0 h-[${px(20)}] bg-[${c.screen}] text-[${keyText}]`}>
      {keys.map(([label, run], i) => (
        <div className="flex flex-1 basis-0 min-w-0 items-center" onClick={run || undefined}>
          <span className={`shrink-0 px-[${px(1)}] text-[${c.keyNum}]`}>{String(i + 1)}</span>
          <div className={`flex flex-1 min-w-0 h-full items-center px-[${px(1)}] bg-[${c.keyBg}] text-[${c.keyText}]`}>
            <span className="truncate">{label}</span>
          </div>
        </div>
      ))}
    </div>
  ) : null

  if (on(app.state.view)) {
    return (
      <div className={`flex flex-col w-full h-full bg-[${c.screen}] text-[${px(14)}]`}>
        <div className="flex flex-col flex-1 min-h-0">
          <yield />
        </div>
        {keyBar}
      </div>
    )
  }

  const terminal = findScene(app, isTerminal)
  const prompt = `${pathOf(panels[side] || current, names)}>`
  return (
    <div className={`relative flex flex-col w-full h-full bg-[${c.screen}] text-[${px(14)}]`}>
      <div className={`flex ${stacked ? 'flex-col' : ''} flex-1 min-h-0`}>
        {panelOf(0)}
        {panelOf(1)}
      </div>
      <div
        className={`flex items-center shrink-0 h-[${px(20)}] px-[${px(2)}] gap-[${px(2)}] text-[${c.prompt}]`}
        onClick={terminal && desk ? () => act.go(terminal.id) : act.sceneList}
      >
        <span className="truncate">{prompt}</span>
        <div className={`shrink-0 w-[${px(8)}] h-[${px(3)}] mt-[${px(10)}] bg-[${c.prompt}]`} />
      </div>
      {keyBar}
      <div
        className={`absolute right-0 top-0 flex items-center h-[${px(16)}] px-[${px(4)}] bg-[${c.lit}] text-[${c.litText}]`}
        onClick={act.frame}
      >
        <span className="leading-[1]">{clock(now)}</span>
      </div>
    </div>
  )
}

