// NeXTSTEP around the scene it wraps, in its four greys: the main menu down the
// top left, the scene in a window with a black title bar and a resize bar, and
// the Dock down the right edge. The menu's Info has the frame's page (Info
// Panel) and the scene's settings (Inspector), Scenes the scene list; the
// Dock's first tile, the FrameOS mark, opens the scene list too, and its last,
// the clock with the date, the frame's page. The window's buttons: the one at
// the left miniaturizes it (a miniwindow under the menu brings it back), the X
// closes the scene to the list, the gear opens its settings. Built-in scenes are
// drawn in the window too.
//
// On a frame that runs its scenes side by side (app.frame.scenes is there), it is
// a desktop: every scene opened is a window, and they all run at once (on an ESP32
// as many as app.frame.windows says, and one more opened closes the one that had
// the focus longest ago), and chosen in another desktop's place (the frame page's
// Layout), it opens what that one had open. A window opens at the layout's "Window
// size" (800x480, a 7.5-inch frame's, unless it says otherwise), filling the
// desktop where that does not fit, and where it was when its scene opens again.
// The scene with the focus is the frame's own (the <yield />), the others are
// <Scene>s. Drag a title bar to move a window, the resize bar's ends or an edge to
// size it, double click the title bar to zoom it to the desktop, let it go at the
// top edge to fill it or at a side to take that half. The Dock has every scene,
// the NeXT ellipsis under the ones not running (a click opens one), then the
// scene store, the terminal and the asset browser where the frame has them, and
// the frame's page last. The main menu is named for the window in front: Info,
// Scenes (the frame's scenes, the scene list), Windows (the windows open, Full
// Screen, Miniaturize Window, Close Window), Services (the store, the terminal,
// the asset browser) and Hide. F11 gives the panel to the window in front
// (Escape takes it back, and the pointer at the left edge brings the menu).
// Alt+Tab goes between windows, Alt+F4 or Cmd+W closes the one in front, Cmd+M
// and Cmd+H miniaturize it. The frame's own scenes open in windows of their own
// over the scene, stay open while another window has the focus, and close when
// they go back by themselves (Save, Cancel, a scene picked).
const pad = (n) => String(n).padStart(2, '0')
const on = (value) => value === true || value === 'true'
const DAYS = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT']
const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC']

// The frame's own scenes (the contract's `scenes.settings` and `scenes.switcher`),
// and the command that opens each, which also sends it back.
const SETTINGS = 'system/sceneSettings'
// On a desktop every scene's settings are a scene of their own, this and the
// scene's id (the contract's `scenes.settingsWindow`); the plain id is the frame's
// page, Preferences.
const SETTINGS_OF = 'system/sceneSettings#'
const settingsOf = (id) => SETTINGS_OF + id
const settingsFor = (id) => (typeof id === 'string' && id.startsWith(SETTINGS_OF) ? id.slice(SETTINGS_OF.length) : null)
const SWITCHER = 'system/sceneSwitcher'
const commandOf = (id) => (id === SWITCHER ? 'sceneSwitcher' : 'sceneSettings')
const isSystem = (id) => typeof id === 'string' && id.startsWith('system/')
// The frame's own apps that are scenes like any other, which the frame may have
// (docs/scene-store.md, docs/terminal.md): the scene store, the asset browser
// and the terminal, by their sample's id, or by their name where a control plane
// gave them another id. A desktop has entries of its own for them, and leaves
// them out of its scene lists.
const appIs = (id, name) => (scene) =>
  !!scene && (scene.id === id || String(scene.name || '').trim().toLowerCase() === name)
const isStore = appIs('scene-store', 'scene store')
const isAssets = appIs('asset-browser', 'asset browser')
const isTerminal = appIs('terminal-app', 'terminal')
const isFrameApp = (scene) => isStore(scene) || isAssets(scene) || isTerminal(scene)
const findScene = (app, test) => (Array.isArray(app.frame.scenes) ? app.frame.scenes.find(test) : undefined)
const storeOf = (app) => findScene(app, isStore)
const assetsOf = (app) => findScene(app, isAssets)
const terminalOf = (app) => findScene(app, isTerminal)
const BAG = 'M6 7V6a6 6 0 0 1 12 0v1h2.5l-1 15h-15l-1-15ZM8 7h8V6a4 4 0 0 0-8 0Z'

// The four greys, and nothing else: one look on a screen, a grey panel and
// black-and-white e-paper alike.
const BLACK = '#000000'
const DARK = '#555555'
const LIGHT = '#aaaaaa'
const WHITE = '#ffffff'

// ------------------------------------------------------------ the frame's pages
//
// The frame's own pages (a scene's settings, the frame's, the scene list, the
// keyboard on the screen) in this layout's look: a theme is each
// kind of element's classes (docs/jsx-ui.md "Themes"), a string for one box or a
// list for boxes inside each other (a bevel is two, as a box has one border
// color). The layout keeps it in its state as `theme`, where the frame reads it;
// not on e-paper but for high contrast.
const CONTRAST = {
  page: 'bg-black text-white',
  bar: 'border-b-2 border-white',
  button: 'font-bold bg-black text-white border-2 border-white active:bg-white active:text-black',
  primary: 'font-bold bg-white text-black border-2 border-white active:bg-black active:text-white',
  selected: 'bg-white text-black border-2 border-white',
  field: 'bg-black text-white border-2 border-white placeholder:text-white focus:border-[#ffff00]',
  option: 'active:bg-white active:text-black',
  picked: 'bg-white text-black',
  switch: 'rounded-full border-2 border-white',
  switchOn: 'rounded-full bg-white border-2 border-white',
  knob: 'rounded-full bg-white',
  knobOn: 'rounded-full bg-black',
  muted: 'text-white',
  card: 'border-2 border-white',
  tile: 'bg-black text-white border-2 border-white active:bg-white active:text-black',
  tileLit: 'bg-black text-white border-4 border-[#ffff00]',
  accent: 'bg-[#ffff00]',
  keyboard: 'bg-black text-white border-t-2 border-white',
  key: 'bg-black text-white border-2 border-white active:bg-white active:text-black',
  keyMod: 'bg-black text-[#ffff00] border-2 border-white active:bg-white active:text-black',
  keyLit: 'bg-white text-black border-2 border-white',
}

function dress(app, themes, fallback) {
  const name = String(app.state.look || fallback)
  const theme = name === 'contrast' ? CONTRAST : app.frame.paper ? null : themes[name] || null
  const key = theme ? name : ''
  if ((app.state.themeOf || '') === key) return
  frameos.setState('theme', theme)
  frameos.setState('themeOf', key)
}

// Raised as a NeXT button is (white at the top left, black at the bottom right),
// and sunk as a field is, the other way round.
const RAISED = [
  'bg-[#aaaaaa] text-black border-t-1 border-l-1 border-white active:bg-white active:border-black',
  'border-b-1 border-r-1 border-black active:border-white',
]
const SUNK = ['border-t-1 border-l-1 border-[#555555]', 'border-b-1 border-r-1 border-white']
const LIT = ['bg-white text-black border-t-1 border-l-1 border-black', 'border-b-1 border-r-1 border-white']
const THEMES = {
  nextstep: {
    page: 'bg-[#aaaaaa] text-black',
    bar: 'border-b-1 border-black',
    button: RAISED,
    primary: ['border-1 border-black', ...RAISED],
    selected: LIT,
    field: [...SUNK, 'bg-white text-black placeholder:text-[#555555]'],
    option: 'active:bg-white',
    picked: 'bg-white text-black',
    switch: [...SUNK, 'bg-[#aaaaaa]'],
    switchOn: [...SUNK, 'bg-white'],
    knob: RAISED,
    knobOn: ['bg-[#555555] border-t-1 border-l-1 border-white', 'border-b-1 border-r-1 border-black'],
    muted: 'text-[#555555]',
    card: [...SUNK, 'bg-[#aaaaaa]'],
    tile: RAISED,
    tileLit: ['border-2 border-black', ...LIT],
    accent: 'bg-black',
    keyboard: 'bg-[#aaaaaa] text-black border-t-1 border-white',
    key: RAISED,
    keyMod: ['bg-[#aaaaaa] text-[#555555] border-t-1 border-l-1 border-white active:bg-white', 'border-b-1 border-r-1 border-black'],
    keyLit: LIT,
  },
}

// Sizes are pixels of the desktop's own: twice that from a short side of 2160 (a 4K
// screen), or of 1000 on e-paper, whose pixels are small, and in proportion under
// 480, which has no room for them. The frame's render scale multiplies on top.
let zoom = 1
let edge = 1 // a line's width
let tile = 64 // the Dock's tiles, smaller on a narrow panel
const px = (n) => `${Math.round(n * zoom * 10) / 10}px`
const len = (n) => Math.round(n * zoom)

function clock(now, twentyFour) {
  const minutes = pad(now.getMinutes())
  if (twentyFour) return `${pad(now.getHours())}:${minutes}`
  return `${now.getHours() % 12 || 12}:${minutes} ${now.getHours() < 12 ? 'AM' : 'PM'}`
}

// A box has one border color, so a bevel is two boxes, one inside the other.
const Bevel = ({ className = '', inner = '', onClick, onDoubleClick, children }) => (
  <div
    className={`flex border-t-${edge} border-l-${edge} border-white ${className}`}
    onClick={onClick}
    onDoubleClick={onDoubleClick}
  >
    <div className={`flex flex-1 min-w-0 min-h-0 border-b-${edge} border-r-${edge} border-black ${inner}`}>{children}</div>
  </div>
)

// The FrameOS mark, not NeXT's cube, in the Dock's first tile.
const Mark = ({ size }) => (
  <svg viewBox="0 0 46 54" className={`w-[${size}] h-[${size}]`}>
    <path fill={BLACK} d="M0 0H46V5H5V30H0ZM26 49H41V32H46V54H26Z" />
    <rect x="7" y="36" width="12" height="11" rx="1.4" fill={DARK} />
    <rect x="20" y="24" width="12" height="11" rx="1.4" fill={BLACK} />
    <rect x="33" y="12" width="12.5" height="11.5" rx="1.4" fill={WHITE} stroke={BLACK} strokeWidth="1.4" />
  </svg>
)

const GEAR =
  'M29.4 13.2L29.8 9.1L34.2 9.1L34.6 13.2L37.9 13.9L40 10.4L43.9 12.3L42.5 16.1L45.1 18.3L48.6 16L51.3 19.4L48.3 22.3L49.8 25.3L53.8 24.8L54.8 29L50.9 30.3L50.9 33.7L54.8 35L53.8 39.2L49.8 38.7L48.3 41.7L51.3 44.6L48.6 48L45.1 45.7L42.5 47.9L43.9 51.7L40 53.6L37.9 50.1L34.6 50.8L34.2 54.9L29.8 54.9L29.4 50.8L26.1 50.1L24 53.6L20.1 51.7L21.5 47.9L18.9 45.7L15.4 48L12.7 44.6L15.7 41.7L14.2 38.7L10.2 39.2L9.2 35L13.1 33.7L13.1 30.3L9.2 29L10.2 24.8L14.2 25.3L15.7 22.3L12.7 19.4L15.4 16L18.9 18.3L21.5 16.1L20.1 12.3L24 10.4L26.1 13.9ZM41 32A9 9 0 1 0 23 32A9 9 0 1 0 41 32Z'

// A window's buttons: a raised square with its glyph in black.
const TitleButton = ({ onClick, children }) => (
  <Bevel className={`shrink-0 w-[${px(16)}] h-[${px(16)}] bg-[#aaaaaa] active:bg-white`} inner="items-center justify-center" onClick={onClick}>
    <svg viewBox="0 0 10 10" className={`w-[${px(10)}] h-[${px(10)}]`}>
      {children}
    </svg>
  </Bevel>
)
const MiniGlyph = () => <rect x="2.5" y="2.5" width="5" height="5" fill="none" stroke={BLACK} strokeWidth="1.2" />
const CloseGlyph = () => <path d="M2 2L8 8M8 2L2 8" stroke={BLACK} strokeWidth="1.5" strokeLinecap="square" />
const GearGlyph = () => (
  <g transform="translate(-1.2 -1.2) scale(0.195)">
    <path fill={BLACK} d={GEAR} />
  </g>
)

// The title bar: black on the window with the focus, light grey on the others,
// the name in the middle, miniaturize at the left, the gear and the close
// button at the right.
const TitleBar = ({ title, active, onMini, onGear, onClose, drag = {} }) => (
  <div
    className={`flex items-center shrink-0 h-[${px(22)}] px-[${px(3)}] ${active ? 'bg-black text-white' : 'bg-[#aaaaaa] text-black'}`}
    {...drag}
  >
    <div className="flex flex-1 basis-0 min-w-0 items-center">{onMini ? <TitleButton onClick={onMini}><MiniGlyph /></TitleButton> : null}</div>
    <span className={`shrink min-w-0 truncate font-bold px-[${px(6)}]`}>{title}</span>
    <div className={`flex flex-1 basis-0 min-w-0 items-center justify-end gap-[${px(3)}]`}>
      {onGear ? (
        <TitleButton onClick={onGear}>
          <GearGlyph />
        </TitleButton>
      ) : null}
      {onClose ? (
        <TitleButton onClick={onClose}>
          <CloseGlyph />
        </TitleButton>
      ) : null}
    </div>
  </div>
)

// The resize bar along a window's bottom: three raised parts, the two at the ends
// the corners.
const ResizeBar = () => (
  <div className={`flex shrink-0 h-[${px(9)}] border-t-${edge} border-black bg-[#aaaaaa]`}>
    <Bevel className={`shrink-0 w-[${px(26)}]`} />
    <Bevel className="flex-1" />
    <Bevel className={`shrink-0 w-[${px(26)}]`} />
  </div>
)

// What a window's frame takes around its scene: the border, the title bar and its
// line, and the resize bar.
const chromeW = () => 2 * edge
const chromeH = () => 3 * edge + len(22) + len(9)

// A scene's own icon: its first letter, white on dark grey.
const Letter = ({ name, size }) => (
  <div className={`flex items-center justify-center w-[${px(size)}] h-[${px(size)}] bg-[#555555] border-${edge} border-black`}>
    <span className={`font-bold text-white text-[${px((size * 3) / 5)}]`}>{(String(name).trim()[0] || 'F').toUpperCase()}</span>
  </div>
)

// The Dock's tiles: a raised grey square each, the NeXT ellipsis at the bottom
// left of a scene that is not running.
const inner = (n) => (tile * n) / 64
const Tile = ({ idle = false, onClick, children }) => (
  <Bevel className={`relative shrink-0 w-[${px(tile)}] h-[${px(tile)}] bg-[#aaaaaa] active:bg-white`} inner="items-center justify-center" onClick={onClick}>
    {children}
    {idle ? (
      <svg viewBox="0 0 12 3" className={`absolute left-[${px(inner(5))}] bottom-[${px(inner(4))}] w-[${px(inner(12))}] h-[${px(inner(3))}]`}>
        <rect x="0" y="0" width="2" height="2" fill={BLACK} />
        <rect x="5" y="0" width="2" height="2" fill={BLACK} />
        <rect x="10" y="0" width="2" height="2" fill={BLACK} />
      </svg>
    ) : null}
  </Bevel>
)

const StoreGlyph = () => (
  <svg viewBox="0 0 24 24" className={`w-[${px(inner(32))}] h-[${px(inner(32))}]`}>
    <path fill={BLACK} d={BAG} />
  </svg>
)
const TerminalGlyph = () => (
  <svg viewBox="0 0 30 26" className={`w-[${px(inner(36))}] h-[${px(inner(31))}]`}>
    <rect x="0.7" y="0.7" width="28.6" height="24.6" fill={BLACK} stroke={DARK} strokeWidth="1.4" />
    <path d="M6 8L11 13L6 18" fill="none" stroke={WHITE} strokeWidth="2.2" />
    <path d="M14 19H22" fill="none" stroke={WHITE} strokeWidth="2.2" />
  </svg>
)
const AssetsGlyph = () => (
  <svg viewBox="0 0 32 26" className={`w-[${px(inner(36))}] h-[${px(inner(29))}]`}>
    <rect x="1" y="1" width="30" height="24" fill={WHITE} stroke={BLACK} strokeWidth="1.4" />
    <rect x="4" y="4" width="24" height="18" fill={LIGHT} />
    <path d="M4 22L12 12L18 18L22 14L28 22Z" fill={DARK} />
    <circle cx="22" cy="8.5" r="2.4" fill={WHITE} />
  </svg>
)

// The frame's page in the Dock: a clock with the day and the date, as NeXT's
// Preferences had.
const ClockTile = ({ now, twentyFour, onClick }) => (
  <Tile onClick={onClick}>
    <div className={`flex flex-col items-center w-full h-full p-[${px(inner(4))}]`}>
      <div className={`flex items-center justify-center w-full h-[${px(inner(13))}] bg-black text-white text-[${px(inner(10))}]`}>
        <span className="whitespace-nowrap">{clock(now, twentyFour)}</span>
      </div>
      <span className={`font-bold text-[${px(inner(9))}] h-[${px(inner(11))}]`}>{DAYS[now.getDay()]}</span>
      <span className={`font-bold text-[${px(inner(20))}] h-[${px(inner(20))}] leading-none`}>{String(now.getDate())}</span>
      <span className={`font-bold text-[${px(inner(9))}]`}>{MONTHS[now.getMonth()]}</span>
    </div>
  </Tile>
)

// A miniaturized window: a tile with a black strip with its name, under the menu.
const MINI = 60
const Miniwindow = ({ name, x, y, onClick }) => (
  <div
    className={`absolute left-[${x}px] top-[${y}px] w-[${px(MINI)}] h-[${px(MINI)}] flex flex-col bg-[#aaaaaa] border-${edge} border-black`}
    onClick={onClick}
  >
    <div className={`flex items-center shrink-0 h-[${px(12)}] px-[${px(2)}] bg-black text-white text-[${px(9)}]`}>
      <span className="truncate">{name}</span>
    </div>
    <div className="flex flex-1 items-center justify-center">
      <Letter name={name} size={30} />
    </div>
  </div>
)

// The main menu's parts: a black title, and grey raised items, a triangle at the
// right of the ones with a submenu, and the key that does it at the right of
// others. An item stays white while its submenu is open.
const Arrow = () => (
  <svg viewBox="0 0 6 8" className={`shrink-0 w-[${px(6)}] h-[${px(8)}]`}>
    <path d="M0 0L6 4L0 8Z" fill={BLACK} />
  </svg>
)
const MenuTitle = ({ children }) => (
  <div className={`flex items-center shrink-0 h-[${px(22)}] px-[${px(6)}] bg-black text-white font-bold border-b-${edge} border-black`}>
    <span className="truncate">{children}</span>
  </div>
)
const MenuItem = ({ label, keyEq = '', arrow = false, lit = false, mark = false, onClick, onPointerMove }) => (
  <Bevel
    className={`shrink-0 h-[${px(22)}] ${lit ? 'bg-white' : 'bg-[#aaaaaa] active:bg-white'}`}
    inner={`items-center gap-[${px(5)}] pl-[${px(6)}] pr-[${px(5)}]`}
    onClick={onClick}
  >
    {mark ? (
      <svg viewBox="0 0 6 6" className={`shrink-0 w-[${px(6)}] h-[${px(6)}]`}>
        <rect x="0" y="0" width="6" height="6" fill={BLACK} />
      </svg>
    ) : null}
    <span className="flex-1 min-w-0 truncate">{label}</span>
    {arrow ? <Arrow /> : keyEq ? <span className={`shrink-0 text-[${px(11)}]`}>{keyEq}</span> : null}
  </Bevel>
)

// ---------------------------------------------------------------- the desktop
//
// What it keeps, in the layout's state (it goes along from scene to scene, and
// is gone at a restart): `wins`, the windows open in the order they were
// opened, each {id, x, y, w, h, z, max, min, snap}, in the desktop's pixels (x to
// h is the window's own box, kept while it fills the desktop or is snapped to a
// half of it, `snap` 'l' or 'r'; a built-in scene's also its `title`); `boxes`,
// where each scene's window was when it closed, by scene id; `last`, the
// scene that had the focus at the last render; `asked`, the scene this layout last
// brought forward itself; `gone`, the scene whose window was just closed; `menu`,
// the submenu open beside the main menu; `full`, `peek` and `drag`, a move or a
// size in progress.

const winsOf = (app) => (Array.isArray(app.state.wins) ? app.state.wins : [])
const topZ = (wins) => wins.reduce((z, w) => Math.max(z, w.z || 0), 0)

function clamp(win, deskW, deskH) {
  const minW = Math.min(deskW, Math.round(160 * zoom))
  const minH = Math.min(deskH, Math.round(100 * zoom))
  win.w = Math.round(Math.max(minW, Math.min(win.w, deskW)))
  win.h = Math.round(Math.max(minH, Math.min(win.h, deskH)))
  // A title bar stays where the pointer can get at it.
  const grip = Math.round(48 * zoom)
  win.x = Math.round(Math.max(grip - win.w, Math.min(win.x, deskW - grip)))
  win.y = Math.round(Math.max(0, Math.min(win.y, deskH - Math.round(22 * zoom))))
  return win
}

const boxesOf = (app) => (app.state.boxes && typeof app.state.boxes === 'object' ? app.state.boxes : {})

// A closed window's box, for when its scene opens again.
function keep(app, win) {
  const { x, y, w, h, max, snap } = win
  frameos.setState('boxes', { ...boxesOf(app), [win.id]: { x, y, w, h, max, snap } })
}

// The scene's own area in a new window: the scene's own size where it says one
// (`windowSize` in app.frame.scenes, its settings.windowSize), else the layout's
// "Window size" (`WxH`, in a desktop's pixels like every size here); null for the
// whole desktop, which "The whole desktop" keeps for every scene.
function ownSize(app, id) {
  const layout = String(app.state.windowSize || '800x480')
  const scene = layout !== 'max' && Array.isArray(app.frame.scenes) ? app.frame.scenes.find((s) => s.id === id) : null
  const mine = scene ? /^(\d+)x(\d+)$/.exec(String(scene.windowSize || '')) : null
  const m = mine || /^(\d+)x(\d+)$/.exec(layout)
  return m ? { w: Math.round(Number(m[1]) * zoom), h: Math.round(Number(m[2]) * zoom), own: !!mine } : null
}

function placed(app, id, wins, deskW, deskH) {
  const win = { id, z: topZ(wins) + 1 }
  // Where it was when it closed, if it was open before.
  const kept = boxesOf(app)[id]
  if (kept) return clamp({ ...kept, ...win }, deskW, deskH)
  // Otherwise the layout's size, its frame around it, cascading from the corner
  // and all of it on the desktop.
  const step = Math.round(24 * zoom) * (wins.length % 6)
  const size = ownSize(app, id)
  // A scene's own size that does not fit is made smaller, its shape kept, once
  // another window is open: the first one still fills the desktop, below.
  const room = size && size.own ? Math.min((deskW - (chromeW())) / size.w, (deskH - (chromeH())) / size.h) : 1
  const shrink = room >= 1 || !wins.some((other) => !other.min) ? 1 : 0.85 * room
  const w = size ? Math.round(size.w * shrink) + chromeW() : deskW + 1
  const h = size ? Math.round(size.h * shrink) + chromeH() : deskH + 1
  if (w <= deskW && h <= deskH) {
    const x = Math.min(Math.round(24 * zoom) + step, deskW - w)
    const y = Math.min(Math.round(16 * zoom) + step, deskH - h)
    return clamp({ ...win, x, y, w, h, max: false }, deskW, deskH)
  }
  // Where it does not fit, the first window fills the desktop, which is what the
  // frame looked like before anything else was opened, and the next ones take
  // most of it; set to the whole desktop, every one fills it.
  const shown = wins.filter((other) => !other.min).length
  const box = { x: Math.round(24 * zoom) + step, y: Math.round(16 * zoom) + step, w: deskW * 0.66, h: deskH * 0.62 }
  return clamp({ ...win, ...box, max: !size || shown === 0 }, deskW, deskH)
}

// Where each window is, for a desktop chosen in this one's place (`openPlaces`,
// handed over with `openScenes`): by scene id, its box as a share of the whole
// picture, so a desktop whose bars are elsewhere puts it where it was on the glass.
const share = (v) => Math.round(v * 10000) / 10000
function keepPlaces(app, wins, desk, width, height) {
  const places = {}
  for (const w of wins)
    places[w.id] = {
      x: share((desk.x + w.x) / width), y: share((desk.y + w.y) / height),
      w: share(w.w / width), h: share(w.h / height),
      max: !!w.max, snap: w.snap || null, min: !!w.min,
    }
  if (JSON.stringify(places) !== JSON.stringify(app.state.openPlaces || {})) frameos.setState('openPlaces', places)
}
function carriedPlace(app, id, desk, width, height) {
  const p = app.state.openPlaces && app.state.openPlaces[id]
  if (!p || ![p.x, p.y, p.w, p.h].every((v) => typeof v === 'number' && isFinite(v))) return null
  const snap = p.snap === 'l' || p.snap === 'r' ? p.snap : undefined
  return { x: p.x * width - desk.x, y: p.y * height - desk.y, w: p.w * width, h: p.h * height, max: p.max === true, snap, min: p.min === true }
}

// What another desktop had open when this layout was chosen in its place (its
// `openScenes`, handed over by the runtime: docs/scene-layouts.md "Windows"): a
// window each, where it was there (`openPlaces`), or cascading in that order, so
// the one that had the focus is on top.
function opened(app, names, titleOf, deskW, deskH, desk, width, height) {
  const wins = []
  for (const id of Array.isArray(app.state.openScenes) ? app.state.openScenes : []) {
    if (typeof id !== 'string' || wins.some((w) => w.id === id) || !(names[id] || isSystem(id))) continue
    const there = carriedPlace(app, id, desk, width, height)
    const win = there ? clamp({ ...there, id, z: topZ(wins) + 1 }, deskW, deskH) : placed(app, id, wins, deskW, deskH)
    if (isSystem(id)) win.title = titleOf(id, names)
    wins.push(win)
  }
  return wins
}

// What is open, the one with the focus last: what a layout chosen in this one's
// place opens (`openScenes`).
function keepOpen(app, wins, current) {
  const order = wins
    .filter((w) => w.id !== current)
    .sort((a, b) => (a.z || 0) - (b.z || 0))
    .map((w) => w.id)
  if (wins.some((w) => w.id === current)) order.push(current)
  if (JSON.stringify(order) !== JSON.stringify(app.state.openScenes || [])) frameos.setState('openScenes', order)
}

// Where a window is drawn: its own box, the whole desktop, or a half of it.
function boxOf(win, deskW, deskH) {
  const half = Math.round(deskW / 2)
  if (win.max) return { x: 0, y: 0, w: deskW, h: deskH }
  if (win.snap === 'l') return { x: 0, y: 0, w: half, h: deskH }
  if (win.snap === 'r') return { x: half, y: 0, w: deskW - half, h: deskH }
  return { x: win.x, y: win.y, w: win.w, h: win.h }
}

// What a press, a key or a menu does to the windows. Each one reads the state
// afresh: a drag's moves come faster than renders.
function actions(app) {
  const current = app.frame.sceneId
  const update = (id, change) => {
    const next = winsOf(app).map((w) => (w.id === id ? { ...w, ...change(w) } : w))
    frameos.setState('wins', next)
  }
  // Every window this layout brings forward goes through here, so a built-in
  // scene that loses the focus some other way is known to have gone back.
  const go = (id) => {
    frameos.setState('asked', id)
    frameos.dispatch('setCurrentScene', { sceneId: id })
  }
  const focus = (id) => {
    frameos.setState('menu', null)
    update(id, () => ({ min: false }))
    if (id !== current) go(id)
  }
  const open = (id) => {
    frameos.setState('menu', null)
    if (winsOf(app).some((w) => w.id === id)) return focus(id)
    if (id !== current) go(id)
    else if (app.state.gone === id) frameos.setState('gone', null)
  }
  // Read when a handler runs, not when it was drawn: a press before it may have
  // brought another window forward.
  const showing = () => app.frame.sceneId
  const windowOf = (id) => winsOf(app).find((w) => w.id === id)
  // The scene window on top: what Info's Inspector is for, and what a built-in
  // scene opens over.
  const topScene = () =>
    winsOf(app)
      .filter((w) => !isSystem(w.id) && !w.min)
      .sort((a, b) => (b.z || 0) - (a.z || 0))[0]
  // A built-in scene opens over a scene. Over another built-in one, that one stays
  // open in its window, and the scene window on top comes forward to open it over;
  // with none, the built-in one goes back where it came from. Either way the
  // focus is this layout's doing (`asked`): the one left open keeps its window.
  const overAScene = () => {
    const now = showing()
    if (!isSystem(now)) return
    const top = topScene()
    if (top) go(top.id)
    else frameos.dispatch(commandOf(now))
  }
  // A scene's settings, from the gear on its title bar: a window of their own,
  // opened over the scene's window brought forward first; open already, that
  // window comes forward as it was left.
  const sceneSettings = (id) => {
    frameos.setState('menu', null)
    if (windowOf(settingsOf(id))) return focus(settingsOf(id))
    if (id !== showing()) go(id)
    frameos.dispatch('sceneSettings', {})
    frameos.setState('asked', settingsOf(id))
  }
  // Info's Inspector: the scene in front's, or the one on top under a built-in
  // scene's window.
  const frontSettings = () => {
    const now = showing()
    const id = isSystem(now) ? (topScene() || {}).id : now
    if (id) sceneSettings(id)
    else frameos.setState('menu', null)
  }
  // A built-in scene of the frame's, one window each: Preferences (the frame's
  // page: Info Panel, the Dock's clock) and the scene list (the Dock's mark).
  // Open already, it comes forward as it was left.
  const builtIn = (id, command, payload) => () => {
    frameos.setState('menu', null)
    if (windowOf(id)) return focus(id)
    overAScene()
    frameos.dispatch(command, payload)
    frameos.setState('asked', id)
  }
  const controlPanel = builtIn(SETTINGS, 'sceneSettings', { page: 'frame' })
  const sceneList = builtIn(SWITCHER, 'sceneSwitcher', {})
  // The window in front went away: the next one down takes the focus.
  const nextAfter = (id) =>
    winsOf(app)
      .filter((w) => w.id !== id && !w.min)
      .sort((a, b) => (b.z || 0) - (a.z || 0))[0]
  const minimize = (id) => {
    frameos.setState('menu', null)
    update(id, () => ({ min: true }))
    const next = id === current ? nextAfter(id) : null
    if (next) go(next.id)
  }
  // A built-in scene with the focus closes as its own Cancel does, back to the
  // scene it was opened over.
  const close = (id) => {
    frameos.setState('menu', null)
    const next = id === current ? nextAfter(id) : null
    const win = winsOf(app).find((w) => w.id === id)
    if (win) keep(app, win)
    frameos.setState('wins', winsOf(app).filter((w) => w.id !== id))
    if (id !== current) return
    frameos.setState('gone', id)
    frameos.setState('full', false)
    if (isSystem(id)) frameos.dispatch(commandOf(id))
    else if (next) go(next.id)
  }
  const toggleMax = (id) => {
    frameos.setState('menu', null)
    update(id, (w) => ({ max: !w.max, snap: null }))
  }
  const toggleFull = () => {
    frameos.setState('menu', null)
    frameos.setState('peek', false)
    frameos.setState('full', !on(app.state.full))
  }
  // Alt+Tab: the window that had the focus before this one, so twice comes back;
  // with Shift, the one at the bottom, so every window comes round in turn.
  const cycle = (back) => {
    const others = winsOf(app)
      .filter((w) => w.id !== current)
      .sort((a, b) => (b.z || 0) - (a.z || 0))
    const next = back ? others[others.length - 1] : others[0]
    if (next) focus(next.id)
    return !!next
  }
  return {
    update, focus, open, sceneSettings, frontSettings, controlPanel, sceneList, minimize, close, toggleMax,
    toggleFull, cycle,
  }
}

// What a built-in scene's window is called before it has shown its page here.
const titleOf = (id, names) => {
  const scene = settingsFor(id)
  if (scene) return `${names[scene] || scene} Inspector`
  return id === SWITCHER ? 'Scene List' : 'Preferences'
}

// What a built-in scene's window is called, by the page it shows.
function systemTitle(app, names) {
  const scene = settingsFor(app.frame.sceneId)
  if (scene) return `${names[scene] || app.state.openedOver || scene} Inspector`
  if (app.frame.sceneId === SWITCHER) return 'Scene List'
  const page = app.frame.sceneName
  if (page === 'Frame settings') return 'Preferences'
  if (page === 'Layout settings') return 'Workspace Preferences'
  return app.state.openedOver ? `${app.state.openedOver} Inspector` : 'Inspector'
}

// The main menu's width and the Dock's tile for a panel this wide.
function measure(app, width, height) {
  const menuW = len(118)
  tile = width >= 640 * Math.max(zoom, 1) ? 64 : 48
  tile = Math.max(28, Math.min(tile, Math.floor(height / zoom / 4)))
  const dockW = on(app.state.showDock) ? len(tile) : 0
  return { menuW, dockW, deskX: menuW, deskW: Math.max(1, width - menuW - dockW) }
}

// The main menu down the top left, and the submenu open beside it.
function MainMenu({ title, items, menu, sub }) {
  return (
    <div className="absolute left-0 top-0 flex items-start">
      <div className={`flex flex-col w-[${px(118)}] border-${edge} border-black`}>
        <MenuTitle>{title}</MenuTitle>
        {items.map((item) => (
          <MenuItem {...item} lit={!!item.sub && item.sub === menu} />
        ))}
      </div>
      {sub ? (
        // A menu takes a press itself: the cover under it closes the menu on a
        // press, and a render before the release would take the item away from
        // the click.
        <div
          className={`flex flex-col w-[${px(172)}] mt-[${sub.top}px] border-${edge} border-black max-h-[${sub.maxH}px] overflow-y-auto`}
          onPointerDown={() => {}}
        >
          <MenuTitle>{sub.title}</MenuTitle>
          {sub.items.map((item) => (
            <MenuItem {...item} />
          ))}
        </div>
      ) : null}
    </div>
  )
}

const MENU_ITEM = 22 // an item's height, the title's too

function desktop(app, now, width, height) {
  const scale = app.frame.scale || 1
  const builtIn = app.frame.systemScene === true
  const current = app.frame.sceneId
  const names = {}
  for (const scene of app.frame.scenes) names[scene.id] = scene.name || scene.id
  if (!builtIn && current && !names[current]) names[current] = app.frame.sceneName || current
  const store = storeOf(app)
  const assets = assetsOf(app)
  const terminal = terminalOf(app)
  const services = [store, terminal, assets].filter(Boolean)
  const programs = app.frame.scenes.filter((scene) => !isFrameApp(scene))
  const { menuW, dockW, deskX, deskW } = measure(app, width, height)
  const deskH = height
  const desk = { x: deskX, y: 0 }

  // Whatever brought a scene forward (a window, the Dock, a menu, the scene list, a
  // button, the API), its window is open and on top, and the one it took the
  // focus from is next below it. A built-in scene's window is named by what it
  // shows while it has the focus, and closes once it has gone back by itself: the
  // focus left it for a scene, and not because this layout moved it. One that
  // opened another (the gear in a scene's settings opening Preferences) did
  // not go back, and stays open.
  // A layout just chosen in another desktop's place has no windows of its own yet:
  // it opens what that one had open.
  const fresh = !Array.isArray(app.state.wins)
  const saved = fresh ? opened(app, names, titleOf, deskW, deskH, desk, width, height) : winsOf(app)
  const wins = saved.filter((w) => w && (names[w.id] || isSystem(w.id)))
  let changed = fresh ? wins.length > 0 : wins.length !== saved.length
  if (current) {
    let win = wins.find((w) => w.id === current)
    if (!win && app.state.gone !== current) {
      win = placed(app, current, wins, deskW, deskH)
      wins.push(win)
      changed = true
    }
    if (win && builtIn && win.title !== systemTitle(app, names)) {
      win.title = systemTitle(app, names)
      changed = true
    }
    if (app.state.last !== current) {
      if (win && win.min) win.min = false
      const before = wins.find((w) => w.id === app.state.last)
      if (before && isSystem(before.id) && !isSystem(current) && app.state.asked !== current) {
        keep(app, before)
        wins.splice(wins.indexOf(before), 1)
      } else if (before) before.z = topZ(wins) + 1
      if (app.state.gone && app.state.gone !== current) frameos.setState('gone', null)
      if (app.state.asked) frameos.setState('asked', null)
      frameos.setState('last', current)
      changed = true
    }
  }
  // Where only so many scenes run at once (app.frame.windows, an ESP32's few),
  // one more closes the one that had the focus longest ago, its box kept.
  const most = app.frame.windows
  if (most > 0) {
    const others = wins.filter((w) => !isSystem(w.id) && w.id !== current).sort((a, b) => (a.z || 0) - (b.z || 0))
    const room = most - (current && !isSystem(current) && wins.some((w) => w.id === current) ? 1 : 0)
    const gone = others.slice(0, Math.max(0, others.length - room))
    if (gone.length) {
      const boxes = { ...boxesOf(app) }
      for (const win of gone) {
        const { x, y, w, h, max, snap } = win
        boxes[win.id] = { x, y, w, h, max, snap }
        wins.splice(wins.indexOf(win), 1)
      }
      frameos.setState('boxes', boxes)
      changed = true
    }
  }
  if (changed) frameos.setState('wins', wins)
  keepOpen(app, wins, current)
  keepPlaces(app, wins, desk, width, height)
  for (const win of wins) if (isSystem(win.id)) names[win.id] = win.title || titleOf(win.id, names)

  const focused = wins.find((w) => w.id === current && !w.min)
  const full = !!focused && on(app.state.full)
  const menu = app.state.menu || null
  const {
    update, focus, open, sceneSettings, frontSettings, controlPanel, sceneList, minimize, close, toggleMax,
    toggleFull,
  } = actions(app)
  const isOpen = (id) => wins.some((w) => w.id === id)

  // A press on a title bar moves the window, one on its edge or the resize bar
  // sizes it from there; the moves that follow are captured by what was pressed.
  // Let go at the top of the desktop, a moved window fills it, at the left or
  // right edge it takes that half; dragged away again, it has its own size back.
  const startDrag = (drawn, mode) => (e) => {
    // As it is now, not as it was drawn: a size may have come since.
    const win = winsOf(app).find((w) => w.id === drawn.id) || drawn
    const box = boxOf(win, deskW, deskH)
    const docked = !!(win.max || win.snap)
    // A half sized from its edge is a window of that size from then on.
    if (docked && mode !== 'move') update(win.id, () => ({ ...box, snap: null }))
    frameos.setState('drag', {
      id: win.id,
      mode,
      x: e.x,
      y: e.y,
      from: box,
      own: { w: win.w, h: win.h },
      docked: docked && mode === 'move',
      at: null,
    })
    if (win.id !== current) focus(win.id)
  }
  const dragTo = (e) => {
    const drag = app.state.drag
    if (!drag || !e.buttons) return
    const dx = (e.x - drag.x) / scale
    const dy = (e.y - drag.y) / scale
    if (drag.mode === 'move') {
      const x = e.x / scale - deskX
      const y = e.y / scale
      const at = y <= 2 ? 'max' : x <= 2 ? 'l' : x >= deskW - 3 ? 'r' : null
      if (drag.docked) {
        // A press that does not move leaves it be (a double click sizes it back).
        if (Math.abs(dx) + Math.abs(dy) < 8 * zoom) return
        // Its own size, with the pointer as far across the title bar as it was.
        const across = (drag.x / scale - deskX - drag.from.x) / drag.from.w
        const from = { x: drag.x / scale - deskX - across * drag.own.w, y: drag.from.y, w: drag.own.w, h: drag.own.h }
        frameos.setState('drag', { ...drag, at, docked: false, from })
        update(drag.id, () => ({ ...clamp({ ...from, x: from.x + dx, y: from.y + dy }, deskW, deskH), max: false, snap: null }))
        return
      }
      if (at !== drag.at) frameos.setState('drag', { ...drag, at })
    }
    const f = drag.from
    update(drag.id, () => {
      const box = { ...f }
      if (drag.mode === 'move') {
        box.x = f.x + dx
        box.y = f.y + dy
      } else {
        if (drag.mode.includes('l')) {
          box.x = Math.min(f.x + dx, f.x + f.w - 80 * zoom)
          box.w = f.w - (box.x - f.x)
        }
        if (drag.mode.includes('r')) box.w = f.w + dx
        if (drag.mode.includes('t')) {
          box.y = Math.max(0, Math.min(f.y + dy, f.y + f.h - 60 * zoom))
          box.h = f.h - (box.y - f.y)
        }
        if (drag.mode.includes('b')) box.h = f.h + dy
      }
      return clamp(box, deskW, deskH)
    })
  }
  const endDrag = () => {
    const drag = app.state.drag
    frameos.setState('drag', null)
    if (drag && drag.mode === 'move' && drag.at && !drag.docked) {
      update(drag.id, () => (drag.at === 'max' ? { max: true, snap: null } : { max: false, snap: drag.at }))
    }
  }
  // The resize bar's ends are its corners; elsewhere a corner is the last few
  // pixels of an edge.
  const near = 12 * zoom
  const edgeOf = (e) => {
    const bottom = e.localY > e.height - Math.max(near, len(9) + 2 * edge)
    const reach = bottom ? 26 * zoom : near
    const x = e.localX < reach ? 'l' : e.localX > e.width - reach ? 'r' : ''
    const y = e.localY < near ? 't' : bottom ? 'b' : ''
    return y + x || 'b'
  }
  const sizing = (win) => ({
    onPointerDown: (e) => startDrag(win, edgeOf(e))(e),
    onPointerMove: dragTo,
    onPointerUp: endDrag,
  })
  const moving = (win) => ({
    onPointerDown: startDrag(win, 'move'),
    onPointerMove: dragTo,
    onPointerUp: endDrag,
    onDoubleClick: () => toggleMax(win.id),
  })

  const windowOf = (win) => {
    const active = win.id === current
    const box = boxOf(win, deskW, deskH)
    return (
      <div
        className={`absolute left-[${box.x}px] top-[${box.y}px] w-[${box.w}px] h-[${box.h}px] flex flex-col bg-[#aaaaaa] border-${edge} border-black`}
        {...(win.max ? {} : sizing(win))}
      >
        <TitleBar
          title={names[win.id]}
          active={active}
          onMini={() => minimize(win.id)}
          onGear={isSystem(win.id) ? null : () => sceneSettings(win.id)}
          onClose={() => close(win.id)}
          drag={moving(win)}
        />
        <div className={`shrink-0 h-[${edge}px] bg-black`} />
        <div className="relative flex flex-col flex-1 min-h-0">
          {active ? <yield /> : <Scene id={win.id} />}
          {/* A press on a window behind brings it forward, and is only that. */}
          {active ? null : <div className="absolute inset-0" onPointerDown={() => focus(win.id)} />}
        </div>
        <ResizeBar />
      </div>
    )
  }

  // Where a window let go now would go: an outline over the windows.
  const outline = () => {
    const drag = app.state.drag
    if (!drag || drag.mode !== 'move' || !drag.at || drag.docked) return null
    const b = boxOf({ max: drag.at === 'max', snap: drag.at }, deskW, deskH)
    const inset = Math.round(3 * zoom)
    return (
      <div
        className={`absolute left-[${b.x + inset}px] top-[${b.y + inset}px] w-[${b.w - 2 * inset}px] h-[${b.h - 2 * inset}px] border-[${Math.max(2, edge * 2)}px] border-white`}
      />
    )
  }

  // The main menu: named for the window in front, Info, Scenes, Windows, Services
  // where the frame has any of them, and Hide. A submenu opens beside it, level
  // with its item; a press on another item with a submenu goes over to that one.
  const mainMenu = () => {
    const toggle = (id) => () => frameos.setState('menu', menu === id ? null : id)
    const items = [
      { label: 'Info', arrow: true, sub: 'info', onClick: toggle('info') },
      { label: 'Scenes', arrow: true, sub: 'scenes', onClick: toggle('scenes') },
      { label: 'Windows', arrow: true, sub: 'windows', onClick: toggle('windows') },
      ...(services.length ? [{ label: 'Services', arrow: true, sub: 'services', onClick: toggle('services') }] : []),
      { label: 'Hide', keyEq: 'h', onClick: () => (focused ? minimize(focused.id) : frameos.setState('menu', null)) },
    ]
    const index = items.findIndex((item) => item.sub === menu)
    let sub = null
    if (index >= 0) {
      const top = len(MENU_ITEM) * (index + 1) + edge
      const subs = {
        info: {
          title: 'Info',
          items: [
            { label: 'Info Panel…', onClick: controlPanel },
            { label: 'Inspector…', keyEq: '3', onClick: frontSettings },
          ],
        },
        scenes: {
          title: 'Scenes',
          items: [
            ...programs.map((scene) => ({ label: names[scene.id], mark: isOpen(scene.id), onClick: () => open(scene.id) })),
            { label: 'Scene List…', onClick: sceneList },
          ],
        },
        windows: {
          title: 'Windows',
          items: [
            ...wins.map((win) => ({ label: names[win.id], mark: win.id === current, onClick: () => focus(win.id) })),
            ...(focused
              ? [
                  { label: full ? 'Exit Full Screen' : 'Full Screen', onClick: toggleFull },
                  { label: 'Miniaturize Window', keyEq: 'm', onClick: () => minimize(focused.id) },
                  { label: 'Close Window', keyEq: 'w', onClick: () => close(focused.id) },
                ]
              : []),
          ],
        },
        services: {
          title: 'Services',
          items: services.map((scene) => ({
            label: scene === store ? 'Scene Store' : scene === terminal ? 'Terminal' : 'Asset Browser',
            mark: isOpen(scene.id),
            onClick: () => open(scene.id),
          })),
        },
      }
      sub = { ...subs[menu], top, maxH: height - top - len(4) }
    }
    return <MainMenu title={focused ? names[focused.id] : 'Workspace'} items={items} menu={menu} sub={sub} />
  }

  // The Dock down the right edge: the mark (the scene list), every scene (the
  // ellipsis under the ones not running), the store, the terminal and the asset
  // browser where the frame has them, and the frame's page, its clock. Where they
  // do not all fit, the ones not running give way, the scenes at the end first:
  // Scenes and Services have them all.
  const dock = () => {
    const room = Math.max(0, Math.floor(height / len(tile)) - 2)
    const all = [...programs, ...services]
    const kept = new Set()
    for (const scene of [...all.filter((scene) => isOpen(scene.id)), ...all]) if (kept.size < room) kept.add(scene.id)
    const glyph = (scene) =>
      scene === store ? <StoreGlyph /> : scene === terminal ? <TerminalGlyph /> : scene === assets ? <AssetsGlyph /> : (
        <Letter name={names[scene.id]} size={inner(36)} />
      )
    return (
      <div className={`absolute right-0 top-0 w-[${dockW}px] flex flex-col`}>
        <Tile onClick={sceneList}>
          <Mark size={px(inner(38))} />
        </Tile>
        {all
          .filter((scene) => kept.has(scene.id))
          .map((scene) => (
            <Tile idle={!isOpen(scene.id)} onClick={() => open(scene.id)}>
              {glyph(scene)}
            </Tile>
          ))}
        <ClockTile now={now} twentyFour={on(app.state.twentyFourHour)} onClick={controlPanel} />
      </div>
    )
  }

  // Miniaturized windows, under the main menu from the bottom up, as many as fit
  // (Windows has them all).
  const miniwindows = () => {
    const step = len(MINI) + len(6)
    const menuBottom = len(MENU_ITEM) * 6 + len(8)
    return wins
      .filter((w) => w.min)
      .map((win, i) => ({ win, y: height - len(6) - (i + 1) * step + len(6) }))
      .filter(({ y }) => y >= menuBottom)
      .map(({ win, y }) => (
        <Miniwindow name={names[win.id]} x={Math.round((menuW - len(MINI)) / 2)} y={y} onClick={() => focus(win.id)} />
      ))
  }

  const cover = menu ? (
    <div className="absolute inset-0" onPointerDown={() => frameos.setState('menu', null)} onClick={() => {}} />
  ) : null

  if (full) {
    // The panel is the window's. The pointer at the left edge brings the main
    // menu; moved back over the window, it goes again, unless a submenu is open.
    const peek = on(app.state.peek) || !!menu
    return (
      <div className={`relative w-full h-full bg-black text-[${px(13)}]`}>
        <div className="absolute inset-0 flex flex-col">
          <yield />
        </div>
        {!peek ? (
          <div className="absolute left-0 top-0 w-[2px] h-full" onPointerMove={() => frameos.setState('peek', true)} />
        ) : menu ? null : (
          <div
            className={`absolute left-[${menuW}px] top-0 w-[${Math.max(1, width - menuW)}px] h-full`}
            onPointerMove={() => frameos.setState('peek', false)}
          />
        )}
        {cover}
        {peek ? mainMenu() : null}
      </div>
    )
  }

  const shown = wins.filter((w) => !w.min && !(focused && w.id === focused.id)).sort((a, b) => (a.z || 0) - (b.z || 0))
  if (focused) shown.push(focused)
  return (
    <div className={`relative w-full h-full bg-[#555555] text-black text-[${px(13)}]`}>
      <div className={`absolute left-[${deskX}px] top-0 w-[${deskW}px] h-[${deskH}px]`}>
        {shown.map(windowOf)}
        {outline()}
      </div>
      {miniwindows()}
      {dockW ? dock() : null}
      {cover}
      {mainMenu()}
    </div>
  )
}

// F11 gives the panel to the window in front and takes it back; Escape closes a
// submenu and leaves the full screen; Alt+Tab (or Cmd+Tab) brings the window
// before forward (Shift: the one at the bottom), Alt+F4 or Cmd+W closes the one in
// front and Cmd+M or Cmd+H miniaturizes it. The scene heard the key first.
export function onEvent(app, context) {
  if (context.event !== 'keyDown' || !Array.isArray(app.frame.scenes) || !windowsOn(app)) return false
  const payload = context.payload || {}
  const key = payload.key
  if (key === 'F11') {
    frameos.setState('peek', false)
    frameos.setState('full', !on(app.state.full))
    return true
  }
  if (key === 'Escape' && (app.state.menu || on(app.state.full))) {
    frameos.setState('menu', null)
    frameos.setState('full', false)
    return true
  }
  const alt = payload.alt === true
  const cmd = payload.meta === true
  if (key === 'Tab' && (alt || cmd)) return actions(app).cycle(payload.shift === true)
  if (!app.frame.sceneId) return false
  if ((key === 'F4' && alt) || ((key === 'w' || key === 'W') && cmd)) {
    actions(app).close(app.frame.sceneId)
    return true
  }
  if ((key === 'm' || key === 'M' || key === 'h' || key === 'H') && cmd) {
    actions(app).minimize(app.frame.sceneId)
    return true
  }
  return false
}

const windowsOn = (app) => app.state.windows !== false && app.state.windows !== 'false'

export function get(app) {
  // app.frame's size is the panel's over the render scale, before the frame's rotation.
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = turned ? app.frame.height : app.frame.width
  const height = turned ? app.frame.width : app.frame.height
  const shortSide = Math.min(app.frame.width, app.frame.height)
  zoom = shortSide >= (app.frame.paper ? 1000 : 2160) ? 2 : shortSide >= 480 ? 1 : shortSide / 480
  edge = Math.max(1, Math.round(zoom))
  const now = new Date()
  dress(app, THEMES, 'nextstep')
  // The clock changes on the minute: nothing to draw until then.
  frameos.setNextSleep(60 - now.getSeconds())
  if (Array.isArray(app.frame.scenes) && windowsOn(app)) return desktop(app, now, width, height)
  // One scene at a time: nothing else is open, nothing for another layout to open.
  if (Array.isArray(app.state.openScenes) && app.state.openScenes.length) frameos.setState('openScenes', [])
  const { menuW, dockW, deskX, deskW } = measure(app, width, height)
  const name = app.frame.sceneName || 'FrameOS'
  const builtIn = app.frame.systemScene === true
  const settingsOpen = builtIn && name.includes('settings')
  const frameOpen = settingsOpen && name.startsWith('Frame')
  const listOpen = builtIn && !settingsOpen
  const title = listOpen ? 'Scene List' : frameOpen ? 'Preferences' : settingsOpen ? 'Inspector' : name
  // The scene a built-in one opened over keeps its tile in the Dock.
  const scene = builtIn ? app.state.openedOver || '' : name
  const minimized = !builtIn && app.state.minimized === true
  const menu = app.state.menu || null
  // A built-in scene's own command, again, goes back to the scene it opened over.
  const closeBuiltIn = () => frameos.dispatch(settingsOpen ? 'sceneSettings' : 'sceneSwitcher')
  const done = (then) => () => {
    frameos.setState('menu', null)
    then()
  }
  const openList = done(() => frameos.dispatch('sceneSwitcher', { swap: true }))
  const openSettings = done(() => frameos.dispatch('sceneSettings'))
  const openFrame = done(() => frameos.dispatch('sceneSettings', { page: 'frame' }))
  const hide = done(() => (builtIn ? closeBuiltIn() : frameos.setState('minimized', true)))
  const show = done(() => (builtIn ? closeBuiltIn() : frameos.setState('minimized', false)))
  const inset = len(10)
  const items = [
    { label: 'Info', arrow: true, sub: 'info', onClick: () => frameos.setState('menu', menu === 'info' ? null : 'info') },
    { label: 'Scenes', onClick: openList },
    { label: 'Hide', keyEq: 'h', onClick: hide },
  ]
  const sub =
    menu === 'info'
      ? {
          title: 'Info',
          top: len(MENU_ITEM) + edge,
          maxH: height - len(MENU_ITEM) - len(4),
          items: [
            { label: 'Info Panel…', onClick: openFrame },
            { label: 'Inspector…', keyEq: '3', onClick: openSettings },
          ],
        }
      : null
  return (
    <div className={`relative w-full h-full bg-[#555555] text-black text-[${px(13)}]`}>
      {minimized ? null : (
        <div
          className={`absolute left-[${deskX + inset}px] top-[${inset}px] w-[${Math.max(1, deskW - 2 * inset)}px] h-[${Math.max(1, height - 2 * inset)}px] flex flex-col bg-[#aaaaaa] border-${edge} border-black`}
        >
          <TitleBar
            title={title}
            active={true}
            onMini={hide}
            onGear={builtIn ? null : openSettings}
            onClose={builtIn ? closeBuiltIn : openList}
          />
          <div className={`shrink-0 h-[${edge}px] bg-black`} />
          <div className="relative flex flex-col flex-1 min-h-0">
            <yield />
          </div>
          <ResizeBar />
        </div>
      )}
      {minimized ? (
        <Miniwindow name={name} x={Math.round((menuW - len(MINI)) / 2)} y={height - len(MINI) - len(6)} onClick={show} />
      ) : null}
      {dockW ? (
        <div className={`absolute right-0 top-0 w-[${dockW}px] flex flex-col`}>
          <Tile onClick={openList}>
            <Mark size={px(inner(38))} />
          </Tile>
          {scene ? (
            <Tile onClick={minimized || builtIn ? show : hide}>
              <Letter name={scene} size={inner(36)} />
            </Tile>
          ) : null}
          <ClockTile now={now} twentyFour={on(app.state.twentyFourHour)} onClick={openFrame} />
        </div>
      ) : null}
      {menu ? <div className="absolute inset-0" onPointerDown={() => frameos.setState('menu', null)} onClick={() => {}} /> : null}
      <MainMenu title={title} items={items} menu={menu} sub={sub} />
    </div>
  )
}

