sources.app.tsx:
// An e-reader's page around the scene it wraps: the scene's name, the clock and
// the battery along the top, the scene on the page between margins, and a
// footer with where it is in the frame's list and how much of the day is left,
// over a line that fills as the day goes. Tap the name for the scene list, the
// clock or the battery for the frame's page, and the footer's left or right
// half for the scene before or after, as a page is turned.
const pad = (n) => String(n).padStart(2, '0')
const on = (value) => value === true || value === 'true'
const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']

const SWITCHER = 'system/sceneSwitcher'

// Paper, sepia and night; a panel without color has paper and night alone.
const PAGES = {
  paper: { page: '#ffffff', ink: '#111111', faint: '#6b6b6b', rule: '#c8c8c8' },
  sepia: { page: '#f4ecd8', ink: '#5b4636', faint: '#8a7660', rule: '#d6c6a4' },
  night: { page: '#000000', ink: '#e8e8e8', faint: '#9a9a9a', rule: '#4a4a4a' },
}
const MONO = {
  paper: { page: '#ffffff', ink: '#000000', faint: '#000000', rule: '#000000' },
  night: { page: '#000000', ink: '#ffffff', faint: '#ffffff', rule: '#ffffff' },
}

function clock(now, twentyFour) {
  if (twentyFour) return `${pad(now.getHours())}:${pad(now.getMinutes())}`
  return `${now.getHours() % 12 || 12}:${pad(now.getMinutes())} ${now.getHours() < 12 ? 'AM' : 'PM'}`
}

// Three bars for the Wi-Fi signal, nothing on a frame that cannot tell.
function Wifi({ rssi, color }) {
  if (typeof rssi !== 'number') return null
  const level = rssi >= -60 ? 3 : rssi >= -72 ? 2 : 1
  return (
    <svg viewBox="0 0 14 10" className="w-[3.2vh] h-[2.3vh]">
      {[0, 1, 2].map((i) => (
        <rect x={i * 5} y={6 - i * 3} width="3.4" height={4 + i * 3} fill={color} fillOpacity={i < level ? 1 : 0.25} />
      ))}
    </svg>
  )
}

function Battery({ percent, color }) {
  if (typeof percent !== 'number') return null
  return (
    <div className="flex items-center gap-[0.6vh]">
      <svg viewBox="0 0 24 12" className="w-[4.4vh] h-[2.2vh]">
        <rect x="0.75" y="0.75" width="20" height="10.5" rx="1.5" fill="none" stroke={color} strokeWidth="1.5" />
        <rect x="2.5" y="2.5" width={Math.max(1, (16.5 * Math.min(100, percent)) / 100)} height="7" fill={color} />
        <rect x="21.5" y="3.5" width="2" height="5" fill={color} />
      </svg>
      <span>{`${percent}%`}</span>
    </div>
  )
}

// Where the scene is in the frame's list, where the host says.
function placeOf(app) {
  const scenes = Array.isArray(app.frame.scenes) ? app.frame.scenes : null
  if (!scenes || app.frame.systemScene === true) return null
  const at = scenes.findIndex((scene) => scene.id === app.frame.sceneId)
  return at < 0 ? null : { at: at + 1, of: scenes.length }
}

export function get(app) {
  const look = String(app.state.page || 'paper')
  const mono = app.frame.color === false
  const c = (mono ? MONO : PAGES)[look] || (mono ? MONO : PAGES).paper
  const margin = { narrow: 2, normal: 4.5, wide: 8 }[String(app.state.margins)] ?? 4.5
  const showClock = on(app.state.showClock)
  const now = new Date()
  // The clock changes on the minute; without it the page waits for the scene.
  if (showClock) frameos.setNextSleep(60 - now.getSeconds())

  const name = app.frame.sceneId === SWITCHER ? 'Library' : app.frame.sceneName || 'FrameOS'
  const place = placeOf(app)
  const minutes = now.getHours() * 60 + now.getMinutes()
  const share = minutes / 1440
  const left = 1440 - minutes
  const leftText = left >= 60 ? `${Math.floor(left / 60)} h ${left % 60} min left in day` : `${left} min left in day`
  const where = place
    ? `Scene ${place.at} of ${place.of} · ${Math.round((place.at / place.of) * 100)}%`
    : `${DAYS[now.getDay()]}, ${now.getDate()} ${MONTHS[now.getMonth()]}`

  return (
    <div className={`flex flex-col w-full h-full bg-[${c.page}] text-[${c.ink}]`}>
      <div className={`flex items-center h-[8vh] px-[${margin}vw] gap-[2vw] text-[2.6vh]`}>
        <div className="flex flex-1 basis-0 min-w-0 h-full items-center" onClick={() => frameos.dispatch('sceneSwitcher')}>
          <span className="truncate font-serif font-bold">{name}</span>
        </div>
        <div
          className="flex flex-1 basis-0 min-w-0 h-full items-center justify-center"
          onClick={() => frameos.dispatch('sceneSettings', { page: 'frame' })}
        >
          {showClock ? <span className="font-bold whitespace-nowrap">{clock(now, on(app.state.twentyFourHour))}</span> : null}
        </div>
        <div
          className="flex flex-1 basis-0 min-w-0 h-full items-center justify-end gap-[1.5vh]"
          onClick={() => frameos.dispatch('sceneSettings', { page: 'frame' })}
        >
          <Wifi rssi={app.frame.wifiRssi} color={c.ink} />
          <Battery percent={app.frame.batteryPercent} color={c.ink} />
        </div>
      </div>
      <div className={`flex flex-col flex-1 min-h-0 px-[${margin}vw] py-[1vh]`}>
        <yield />
      </div>
      <div className={`flex items-center h-[6.5vh] px-[${margin}vw] gap-[2vw] text-[2.3vh] text-[${c.faint}]`}>
        <div
          className="flex flex-1 basis-0 min-w-0 h-full items-center"
          onClick={() => frameos.dispatch('setCurrentScene', { direction: 'prev' })}
        >
          <span className="truncate">{where}</span>
        </div>
        <div
          className="flex flex-1 basis-0 min-w-0 h-full items-center justify-end"
          onClick={() => frameos.dispatch('setCurrentScene', { direction: 'next' })}
        >
          <span className="truncate">{leftText}</span>
        </div>
      </div>
      {on(app.state.showProgress) ? (
        <div className={`flex items-center h-[2.5vh] px-[${margin}vw] pb-[1.2vh]`}>
          <div className={`relative flex-1 h-[0.5vh] bg-[${c.rule}]`}>
            <div className={`absolute left-0 top-0 h-full w-[${Math.round(share * 1000) / 10}%] bg-[${c.ink}]`} />
          </div>
        </div>
      ) : null}
    </div>
  )
}

