sources.app.tsx:
// A teletext page around the scene it wraps: the header row with the page
// number, the service's name, the date and the clock; a double-height band with
// the scene's name; and the four Fastext links along the bottom. Red and green
// go to the scene before and after, yellow to the index (the scene list), cyan
// to the scene's settings, and the clock to the frame's page. The page number
// is the scene's place in the frame's list (P101 the first), P100 the index.
//
// Eight colors, as a teletext set has: on color e-paper the cyan and magenta it
// cannot show are white, and a black-and-white or grey panel draws it in white
// on black with a shape by each link, as the keys on a remote have.
const pad = (n) => String(n).padStart(2, '0')
const on = (value) => value === true || value === 'true'
const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

const SWITCHER = 'system/sceneSwitcher'
const SETTINGS = 'system/sceneSettings'

const TELETEXT = {
  black: '#000000', red: '#ff0000', green: '#00ff00', yellow: '#ffff00',
  blue: '#0000ff', magenta: '#ff00ff', cyan: '#00ffff', white: '#ffffff',
}

// The colors a panel can show: all eight on a screen; the six inks of color
// e-paper; white alone on a panel without color.
function palette(app) {
  if (app.frame.color === false) {
    const white = TELETEXT.white
    return { ...TELETEXT, red: white, green: white, yellow: white, blue: white, magenta: white, cyan: white, mono: true }
  }
  if (app.frame.paper) return { ...TELETEXT, cyan: TELETEXT.white, magenta: TELETEXT.red, mono: false }
  return { ...TELETEXT, mono: false }
}

// A three-digit page for any scene: its place in the frame's list where the
// host says, otherwise a number of its own made from its id.
function pageOf(app, id) {
  if (id === SWITCHER) return 100
  if (typeof id === 'string' && id.startsWith(SETTINGS)) return 199
  const scenes = Array.isArray(app.frame.scenes) ? app.frame.scenes : null
  const at = scenes ? scenes.findIndex((scene) => scene.id === id) : -1
  if (at >= 0) return Math.min(899, 101 + at)
  let hash = 0
  for (const ch of String(id || app.frame.sceneName || '')) hash = (hash * 31 + ch.charCodeAt(0)) % 100003
  return 101 + (hash % 799)
}

// The scenes a step back and a step on from this one, where the host lists them.
function neighbours(app, id) {
  const scenes = Array.isArray(app.frame.scenes) ? app.frame.scenes : []
  if (scenes.length < 2) return [null, null]
  const at = scenes.findIndex((scene) => scene.id === id)
  if (at < 0) return [null, null]
  return [scenes[(at + scenes.length - 1) % scenes.length], scenes[(at + 1) % scenes.length]]
}

// A block of mosaic: two by three cells a character, set where `rows` has a
// '#'. Drawn as one path, so the band costs one element however many cells.
function Mosaic({ rows, color, className }) {
  const h = rows.length
  const w = rows[0].length
  let d = ''
  rows.forEach((row, y) => {
    for (let x = 0; x < row.length; x++) if (row[x] === '#') d += `M${x} ${y}h1v1h-1Z`
  })
  return (
    <svg viewBox={`0 0 ${w} ${h}`} preserveAspectRatio="none" className={className}>
      <path d={d} fill={color} />
    </svg>
  )
}

// A picture frame in mosaic, the service's mark.
const MARK = [
  '##########',
  '#........#',
  '#.##..##.#',
  '#.######.#',
  '#........#',
  '##########',
]

// The shape by a Fastext link on a panel without color.
function KeyShape({ index, color }) {
  const shapes = [
    <rect x="1" y="1" width="8" height="8" fill={color} />,
    <circle cx="5" cy="5" r="4.2" fill={color} />,
    <path d="M5 0.8L9.4 9H0.6Z" fill={color} />,
    <path d="M5 0.6L9.4 5L5 9.4L0.6 5Z" fill={color} />,
  ]
  return (
    <svg viewBox="0 0 10 10" className="w-[2.2vh] h-[2.2vh] shrink-0">
      {shapes[index]}
    </svg>
  )
}

export function get(app) {
  const c = palette(app)
  const { service, band } = app.state
  const now = new Date()
  const id = app.frame.sceneId || ''
  const builtIn = app.frame.systemScene === true
  const name = app.frame.sceneName || 'FrameOS'
  const title = id === SWITCHER ? 'Index' : name
  const page = pageOf(app, id)
  const seconds = on(app.state.showSeconds) && !app.frame.paper
  const clock = `${pad(now.getHours())}:${pad(now.getMinutes())}${seconds ? `/${pad(now.getSeconds())}` : ''}`
  // The clock changes on the minute, or the second where it shows them.
  frameos.setNextSleep(seconds ? 1 : 60 - now.getSeconds())

  const [before, after] = builtIn ? [null, null] : neighbours(app, id)
  const short = (scene, fallback) => (scene ? String(scene.name || fallback) : fallback)
  const links = [
    { color: c.red, label: short(before, 'Previous'), go: () => frameos.dispatch('setCurrentScene', { direction: 'prev' }) },
    { color: c.green, label: short(after, 'Next'), go: () => frameos.dispatch('setCurrentScene', { direction: 'next' }) },
    { color: c.yellow, label: 'Index', go: () => frameos.dispatch('sceneSwitcher') },
    { color: c.cyan, label: 'Settings', go: () => frameos.dispatch('sceneSettings') },
  ]
  // The band's color: one of the six a set has beside black and white; on a
  // panel without color it is white, the name black on it.
  const bandColor = c.mono ? c.white : c[band] || c.blue
  const bandInk = c.mono || band === 'yellow' || band === 'cyan' || band === 'green' ? c.black : c.yellow
  const markColor = c.mono ? c.black : band === 'yellow' || band === 'cyan' ? c.blue : c.cyan

  return (
    <div className={`flex flex-col w-full h-full bg-black text-white font-bold`}>
      <div
        className="flex items-center h-[4vh] px-[1.25vw] gap-[1.5vw] text-[3vh] whitespace-nowrap"
        onClick={() => frameos.dispatch('sceneSettings', { page: 'frame' })}
      >
        <span className="shrink-0">{`P${page}`}</span>
        <span className="shrink min-w-0 truncate">{String(service || 'FRAMETEXT').toUpperCase()}</span>
        <span className="shrink-0">{String(page)}</span>
        <div className="flex-1" />
        <span className="shrink-0">{`${DAYS[now.getDay()]} ${pad(now.getDate())} ${MONTHS[now.getMonth()]}`}</span>
        <span className={`shrink-0 text-[${c.yellow}]`}>{clock}</span>
      </div>
      <div
        className={`flex items-center shrink-0 h-[9vh] mx-[1.25vw] mt-[0.5vh] px-[1.5vw] gap-[2vw] bg-[${bandColor}]`}
        onClick={() => frameos.dispatch('sceneSwitcher')}
      >
        <Mosaic rows={MARK} color={markColor} className="w-[9vh] h-[6vh] shrink-0" />
        <span className={`shrink min-w-0 truncate text-[6.5vh] leading-[1] uppercase text-[${bandInk}]`}>{title}</span>
      </div>
      <div className="flex flex-col flex-1 min-h-0 px-[1.25vw] pt-[1vh] pb-[0.5vh]">
        <yield />
      </div>
      <div className="flex items-center h-[5vh] px-[1.25vw] gap-[2vw] text-[3vh]">
        {links.map((link, i) => (
          <div className="flex flex-1 basis-0 min-w-0 items-center gap-[0.8vw] h-full" onClick={link.go}>
            {c.mono ? <KeyShape index={i} color={c.white} /> : null}
            <span className={`truncate text-[${link.color}]`}>{link.label}</span>
          </div>
        ))}
      </div>
    </div>
  )
}

