// A bar above the scene it wraps: a title, the time, the Wi-Fi signal and the battery.
const pad = (n) => String(n).padStart(2, '0')
const on = (value) => value === true || value === 'true'

const clock = (now, seconds) =>
  `${pad(now.getHours())}:${pad(now.getMinutes())}${seconds ? `:${pad(now.getSeconds())}` : ''}`

// Four bars for the Wi-Fi signal, nothing on a frame that cannot tell.
function Signal({ rssi, color }) {
  if (typeof rssi !== 'number') return null
  const level = rssi >= -55 ? 4 : rssi >= -65 ? 3 : rssi >= -75 ? 2 : 1
  return (
    <div className="flex items-end gap-[0.4vh] h-[3vh]">
      {[1.2, 1.8, 2.4, 3].map((height, i) => (
        <div className={`w-[0.7vh] h-[${height}vh] bg-[${color}] ${i < level ? '' : 'opacity-30'}`} />
      ))}
    </div>
  )
}

const Battery = ({ percent }) => (typeof percent === 'number' ? <span>{`${percent}%`}</span> : null)

export function get(app) {
  const { title, barColor, textColor, showSeconds } = app.state
  return (
    <div className={`flex flex-col w-full h-full bg-[${barColor}] text-[${textColor}]`}>
      <div className="flex items-center h-[9vh] px-[3vw] gap-[2vw]">
        <span className="flex-1 text-[3.6vh] font-semibold truncate">{title}</span>
        <span className="text-[5vh] font-bold">{clock(new Date(), on(showSeconds))}</span>
        <div className="flex-1 flex items-center justify-end gap-[1.5vw] text-[3vh] font-semibold">
          <Signal rssi={app.frame.wifiRssi} color={textColor} />
          <Battery percent={app.frame.batteryPercent} />
        </div>
      </div>
      <yield />
    </div>
  )
}
